(window.EX_CHUNKS=window.EX_CHUNKS||{})["b63"]={"不客气":[["谢谢你的帮助。”“不客气。","ياردەم قىلغىنىڭىزغا رەھمەت.» «مەيلى، رەھمەت دېمەڭ.","Yardem qilghiningizgha rehmet.» «Meyli, rehmet dëmeng."]],"羊肉":[["这道菜是用羊肉做的。","بۇ تاماق قوي گۆشىدىن پىشۇرۇلغان.","Bu tamaq qoy göshidin pishurulghan."]],"面条":[["这碗面条真好吃！","بۇ قاچا لىۋان ھەقىقەتەن بەك مەززىلىك!","Bu qacha liwan heqiqeten bek mezzilik!"]],"古董":[["这件瓷器是真正的古董。","بۇ فارفور بۇيۇمى ھەقىقىي قەدىمكى ئەسەر.","Bu farfor buyumi heqiqiy qedimki eser."]],"请帖":[["收到了朋友的结婚请帖，真为他高兴。","دوستۇمنىڭ توي تەكلىپنامىسىنى ئالدىم، ئۇنىڭ ئۈچۈن بەك خۇشال بولدۇم.","Dostumning toy teklipnamisini aldim, uning üchün bek xushal boldum."]],"呿":[["他“呿”了一声。","ئۇ «چى» دەپ بىر ئاۋاز چىقاردى.","U «chi» dep bir awaz chiqardi."]],"恿":[["他怂恿人冒险，不顾后果。","ئۇ كىشىلەرنى خەتەرگە تىكىپ، ئاقىۋەتنى ئويلاشمايدۇ.","U kishilerni xeterge tikip, aqiwetni oylashmaydu."]],"橿":[["橿树的叶子呈椭圆形。","ئۇدۇن دەرىخىنىڭ يوپۇرماقلىرى ئېللىپس شەكىللىك بولىدۇ.","Udun derixining yopurmaqliri ëllips shekillik bolidu."]],"梿":[["梿木常被用来制作家具。","زەرەڭ ياغىچى كۆپىنچە ئۆي جاھازىسى ياساشقا ئىشلىتىلىدۇ.","Zereng yaghichi köpinche öy jahazisi yasashqa ishlitilidu."]],"瑿":[["他收藏了许多珍贵的瑿石。","ئۇ نۇرغۇن قىممەتلىك يۈشلارنى توپلىغان.","U nurghun qimmetlik yüshlarni toplighan."]],"窿":[["墙上突然出现了一个大窿。","تامدا تۇيۇقسىز بىر چوڭ تۆشۈك پەيدا بولدى.","Tamda tuyuqsiz bir chong töshük peyda boldi."]],"蓿":[["苜蓿草富含多种营养成分。","بېدە ئوتى كۆپ خىل ئوزۇقلۇق تەركىبىگە باي.","Bëde oti köp xil ozuqluq terkibige bay."]],"芿":[["芿草在风中轻轻摇曳。","ئوت-چۆپلەر شامالدا ئاستا تەۋرىنىدۇ.","Ot-chöpler shamalda asta tewrinidu."]],"薿":[["薿是古代的一种草。","نىي قەدىمكى زاماندىكى بىر خىل ئوت.","Niy qedimki zamandiki bir xil ot."]],"蚿":[["蚿虫的触角非常灵敏。","قۇرتقۇچ قۇرتىنىڭ مۈڭگۈزى ئىنتايىن سەزگۈر.","Qurtquch qurtining münggüzi intayin sezgür."]],"邿":[["邿山是当地著名的旅游景点。","شى تېغى يەرلىك داڭلىق ساياھەت نۇقتىسى.","Shi tëghi yerlik dangliq sayahet nuqtisi."]],"迿":[["他迿过人群走向出口。","ئۇ ئادەم توپى ئىچىدىن ئۆتۈپ چىقىش ئېغىزىغا قاراپ ماڭدى.","U adem topi ichidin ötüp chiqish ëghizigha qarap mangdi."]],"鲿":[["鲿鱼属于鲇科鱼类。","چاڭ بېلىقى يىلان بېلىقى ئائىلىسى بېلىقلىرىغا تەۋە.","Chang bëliqi yilan bëliqi a'ilisi bëliqlirigha tewe."]],"鱿":[["鱿鱼是海洋中的常见生物。","كالمار دېڭىزدىكى كۆپ ئۇچرايدىغان جانلىقلاردىن بىرى.","Kalmar dëngizdiki köp uchraydighan janliqlardin biri."]],"一小撮":[["他抓了一小撮盐撒在菜里。","ئۇ بىر چىمىدەك تۇزنى ئېلىپ تاماققا سالدى.","U bir chimidek tuzni ëlip tamaqqa saldi."]],"一山不容二虎":[["一山不容二虎，公司只能选一位领导。","بىر تاغدا ئىككى يولۋاس تۇرالمايدۇ، شىركەت پەقەت بىر رەھبەرنىلا تاللىيالايدۇ.","Bir taghda ikki yolwas turalmaydu, shirket peqet bir rehbernila talliyalaydu."]],"一日之雅":[["一日之雅难以持久。","بىر كۈنلۈك يېقىنلىق ئۇزاققا سۈرۈلمەيدۇ.","Bir künlük yëqinliq uzaqqa sürülmeydu."]],"一致性效应":[["一致性效应会影响用户体验。","بىر تۇتاشلىق ئۈنۈمى ئىشلەتكۈچى تەجرىبىسىگە تەسىر كۆرسىتىدۇ.","Bir tutashliq ünümi ishletküchi tejribisige tesir körsitidu."]],"一蹴而得":[["机会并非一蹴而得，要耐心等待。","پۇرسەت بىرلا قەدەمدە قولغا كەلمەيدۇ، سەۋر بىلەن كۈتۈش كېرەك.","Purset birla qedemde qolgha kelmeydu, sewr bilen kütüsh kërek."]],"一览无遗":[["从山顶可一览无遗。","تاغ چوققىسىدىن ھەممە يەرنى بىر قاراشتا كۆرگىلى بولىدۇ.","Tagh choqqisidin hemme yerni bir qarashta körgili bolidu."]],"一言难尽":[["这段经历一言难尽，难以描述。","بۇ تەجرىبىنى بىر ئېغىز سۆز بىلەن تەسۋىرلەش تەس، تەسۋىرلەش قىيىن.","Bu tejribini bir ëghiz söz bilen teswirlesh tes, teswirlesh qiyin."]],"丁卯战争":[["丁卯战争是历史上一次重要的军事冲突。","دىڭماۋ ئۇرۇشى تارىختىكى مۇھىم بىر ھەربىي توقۇنۇش.","Dingmaw urushi tarixtiki muhim bir herbiy toqunush."]],"三都水族自治县":[["这里是三都水族自治县。","بۇ يەر ئۈچ دۇ شۇي مىللىتى ئاپتونوم ناھىيىسى.","Bu yer üch du shuy milliti aptonom nahiyisi."]],"三酸甘油酯":[["三酸甘油酯是常见物质。","ئۈچ كىسلاتالىق گلىتسېرىد ئادەتتە ئۇچرايدىغان ماددىدۇر.","Üch kislataliq glitsërid adette uchraydighan maddidur."]],"上一页":[["点击返回上一页。","قايتۇرۇش كۇنۇپكىسىنى چېكىپ ئالدىنقى بەتكە قايتىڭ.","Qayturush kunupkisini chëkip aldinqi betke qayting."]],"三门":[["三门是著名景点。","سانمېن مەشھۇر مەنزىرە نۇقتىسى.","Sanmën meshhur menzire nuqtisi."]],"三项式":[["数学中的三项式很重要。","ماتېماتىكىدىكى ئۈچ ئەزالىق ئىپادە بەك مۇھىم.","Matëmatikidiki üch ezaliq ipade bek muhim."]],"不可多得":[["这种人才真是不可多得。","بۇنداق ئىختىساسلىق كىشىلەر ھەقىقەتەن ئاز ئۇچرايدۇ.","Bundaq ixtisasliq kishiler heqiqeten az uchraydu."]],"上等":[["这件衣服质量上等。","بۇ كىيىمنىڭ سۈپىتى ئالىي دەرىجىلىك.","Bu kiyimning süpiti aliy derijilik."]],"下陆区":[["下陆区是这座城市的历史中心。","شياگۇەن رايونى بۇ شەھەرنىڭ تارىخىي مەركىزىدۇر.","Shyaguen rayoni bu sheherning tarixiy merkizidur."]],"鄿":[["鄿村保留着许多传统的民俗活动。","شىن كەنتىدە نۇرغۇن ئەنئەنىۋى خەلق ئۆرپ-ئادەتلىرى ساقلىنىپ قالغان.","Shin kentide nurghun en'eniwi xelq örp-adetliri saqlinip qalghan."]],"下议院":[["下议院负责立法。","تۆۋەنكى پالاتا قانۇن چىقىرىشقا مەسئۇل.","Töwenki palata qanun chiqirishqa mes'ul."]],"下跪":[["他被迫下跪道歉。","ئۇ مەجبۇرلىنىپ تىزلىنىپ كەچۈرۈم سورىدى.","U mejburlinip tizlinip kechürüm soridi."]],"不敬":[["这是对长辈的不敬。","بۇ چوڭلارغا ھۆرمەتسىزلىك قىلغانلىق.","Bu chonglargha hörmetsizlik qilghanliq."]],"不咎既往":[["他决定不咎既往，重新开始。","ئۇ ئۆتكەن ئىشلارنى سورىماسلىقنى قارار قىلىپ، يېڭىدىن باشلىدى.","U ötken ishlarni sorimasliqni qarar qilip, yëngidin bashlidi."]],"不经之谈":[["这真是不经之谈。","بۇ ھەقىقەتەن ئاساسسىز گەپ.","Bu heqiqeten asassiz gep."]],"不独":[["这件事不独他一人负责。","بۇ ئىشقا پەقەت ئۇ يالغۇز مەسئۇل ئەمەس.","Bu ishqa peqet u yalghuz mes'ul emes."]],"并系群":[["多个系统并系群运行。","كۆپلىگەن سىستېمىلار پاراللېل گۇرۇپپا ھالىتىدە يۈرگۈزۈلىدۇ.","Köpligen sistëmilar parallël guruppa halitide yürgüzülidu."]],"丘北":[["丘北的梯田风景如画。","چيۇبېي تېرىقچىلىقى مەنزىرىسى رەسىمدەك گۈزەل.","Chyubëy tëriqchiliqi menzirisi resimdek güzel."]],"中和":[["中和能缓解冲突。","ئوتتۇراھال توقۇنۇشنى يېنىكلىتەلەيدۇ.","Otturahal toqunushni yënikliteleydu."]],"中国经营报":[["《中国经营报》报道了最新的经济政策。","«جۇڭگو باشقۇرۇش گېزىتى» ئەڭ يېڭى ئىقتىساد سىياسىتىنى خەۋەر قىلدى.","«Junggo bashqurush gëziti» eng yëngi iqtisad siyasitini xewer qildi."]],"中央研究院":[["中央研究院从事学术研究。","مەركىزىي تەتقىقات ئورنى ئىلمىي تەتقىقات بىلەن شۇغۇللىنىدۇ.","Merkiziy tetqiqat orni ilmiy tetqiqat bilen shughullinidu."]],"并行不悖":[["两种方案可以并行不悖地实施。","ئىككى خىل پىلاننى بىرلا ۋاقىتتا زىددىيەتسىز ئەمەلگە ئاشۇرغىلى بولىدۇ.","Ikki xil pilanni birla waqitta ziddiyetsiz emelge ashurghili bolidu."]],"中间商":[["中间商赚取了差价。","ئوتتۇرا سودىگەر باھا پەرقىدىن پايدا ئالدى.","Ottura sodiger baha perqidin payda aldi."]],"主业":[["他的主业是软件开发。","ئۇنىڭ ئاساسلىق كەسپى يۇمشاق دېتال تەرەققىياتى.","Uning asasliq kespi yumshaq dëtal tereqqiyati."]],"主管机关":[["主管机关拥有决策权。","باشقۇرۇش ئورگىنى قارار قىلىش ھوقۇقىغا ئىگە.","Bashqurush orgini qarar qilish hoquqigha ige."]],"主罚":[["主罚球员被红牌罚下。","باش جازا ئوينىغۇچى قىزىل كارتىدا چىقىرىۋېتىلدى.","Bash jaza oynighuchi qizil kartida chiqiriwëtildi."]],"中央情报局":[["中央情报局负责情报收集。","مەركىزىي ئۇچۇر ئىدارىسى ئۇچۇر توپلاشقا مەسئۇلدۇر.","Merkiziy uchur idarisi uchur toplashqa mes'uldur."]],"幺点":[["这个幺点在图表中格外显眼。","بۇ كىچىك نۇقتا دىئاگراممىدا ئالاھىدە كۆزگە چېلىقىدۇ.","Bu kichik nuqta di'agrammida alahide közge chëliqidu."]],"乙酸":[["乙酸是食醋的主要成分，具有酸性。","ئاتسېتىك كىسلاتا ئاچچىق سىرنىڭ ئاساسلىق تەركىبىي قىسمى بولۇپ، كىسلاتالىق خاسلىققا ئىگە.","Atsëtik kislata achchiq sirning asasliq terkibiy qismi bolup, kislataliq xasliqqa ige."]],"乖迕":[["他的行为乖迕常理，让人摸不着头脑。","ئۇنىڭ قىلمىشى نورمال ئەقىلگە ئۇيغۇن ئەمەس، كىشىنى ھەيران قالدۇرىدۇ.","Uning qilmishi normal eqilge uyghun emes, kishini heyran qalduridu."]],"二手":[["这件衣服是二手的，价格便宜。","بۇ كىيىم ئىككىنچى قول، باھاسى ئەرزان.","Bu kiyim ikkinchi qol, bahasi erzan."]],"二水货":[["这个二水货质量太差了。","بۇ دىسۇ مالنىڭ سۈپىتى بەك ناچار.","Bu disu malning süpiti bek nachar."]],"二分点":[["二分点是数学中的一个概念。","ئىككى بۆلەكلىك نۇقتا ماتېماتىكىدا بىر ئۇقۇم.","Ikki böleklik nuqta matëmatikida bir uqum."]],"二十一世纪":[["二十一世纪是2001年开始的。","يىگىرمە بىرىنچى ئەسىر 2001-يىلىدىن باشلانغان.","Yigirme birinchi esir 2001-yilidin bashlan'ghan."]],"五结":[["这个地方的习俗被称为五结。","بۇ جاينىڭ ئادەت-رەسىمى «ۋۇجيې» دەپ ئاتىلىدۇ.","Bu jayning adet-resimi «wujyë» dep atilidu."]],"五声音阶":[["五声音阶由五个基本音组成，常用于音乐创作。","بەش ئاۋازلىق پەلەمپەي بەش ئاساسىي ئاۋازدىن تەركىب تاپقان بولۇپ، مۇزىكا ئىجادىيىتىدە كۆپ ئىشلىتىلىدۇ.","Besh awazliq pelempey besh asasiy awazdin terkib tapqan bolup, muzika ijadiyitide köp ishlitilidu."]],"五脏六腑":[["五脏六腑是中医对人体内部器官的统称。","بەش ئىچكى ئەزا ۋە ئالتە ئىچكى ئەزا جۇڭگو تېبابىتىدە ئىنسان بەدىنىنىڭ ئىچكى ئەزالىرىنىڭ ئومۇمىي ئاتىلىشى.","Besh ichki eza we alte ichki eza junggo tëbabitide insan bedinining ichki ezalirining omumiy atilishi."]],"亚洲开发银行":[["亚洲开发银行支持区域经济发展。","ئاسىيا تەرەققىيات بانكىسى رايون ئىقتىسادىنىڭ تەرەققىياتىنى قوللايدۇ.","Asiya tereqqiyat bankisi rayon iqtisadining tereqqiyatini qollaydu."]],"交口":[["大家交口称赞他的才华。","ھەممەيلەن ئۇنىڭ تالانتىنى ئاغزى-ئاغزىغا تەگمەي ماختاشتى.","Hemmeylen uning talantini aghzi-aghzigha tegmey maxtashti."]],"交通堵塞":[["早高峰时段的交通堵塞十分严重。","ئەتىگەنكى ئالدىراش ۋاقىتتىكى قاتناش تۇتىلىشى ئىنتايىن ئېغىر.","Etigenki aldirash waqittiki qatnash tutilishi intayin ëghir."]],"京九铁路":[["京九铁路连接北京与九龙。","جىڭجيو تۆمۈريولى بېيجىڭ بىلەن جيۇلۇڭنى تۇتاشتۇرىدۇ.","Jingjyo tömüryoli bëyjing bilen jyulungni tutashturidu."]],"仁惠":[["公司推出仁惠政策，惠及民众。","شىركەت مېھرىبانلىق سىياسىتىنى ئوتتۇرىغا قويۇپ، خەلققە مەنپەئەت يەتكۈزدى.","Shirket mëhribanliq siyasitini otturigha qoyup, xelqqe menpe'et yetküzdi."]],"人去楼空":[["人去楼空，只剩一片寂静。","ئادەملەر كەتتى، بىنا بوش قالدى، پەقەت جىمجىتلىقلا قالدى.","Ademler ketti, bina bosh qaldi, peqet jimjitliqla qaldi."]],"代尔夫特":[["代尔夫特大学很有名。","دېلفت ئۇنىۋېرسىتېتى ناھايىتى داڭلىق.","Dëlft uniwërsitëti nahayiti dangliq."]],"仙游":[["他常去仙游欣赏美景。","ئۇ دائىم شىيەنيۇغا بېرىپ گۈزەل مەنزىرىلەردىن ھۇزۇرلىنىدۇ.","U da'im shiyenyugha bërip güzel menzirilerdin huzurlinidu."]],"代数和":[["代数和是代数运算的基础。","ئالگېبرالىق يىغىندا ئالگېبرا ئەمەلىيىتىنىڭ ئاساسىدۇر.","Algëbraliq yighinda algëbra emeliyitining asasidur."]],"伊春区":[["伊春区位于黑龙江省中部。","ئىچۈن رايونى خېيلۇڭجياڭ ئۆلكىسىنىڭ مەركىزىدە جايلاشقان.","Ichün rayoni xëylungjyang ölkisining merkizide jaylashqan."]],"伊甸园":[["伊甸园是《圣经》中描述的理想之地。","ئېدېن باغچىسى «ئىنجىل»دا تەسۋىرلەنگەن ئىدېئال جاي.","Ëdën baghchisi «injil»da teswirlen'gen idë'al jay."]],"伯莎":[["伯莎是一位勇敢的女性。","بېرسا بىر باتۇر ئايال.","Bërsa bir batur ayal."]],"佛寺":[["清晨的佛寺里弥漫着檀香与诵经声。","ئەتىگەنكى بۇددا ئىبادەتخانىسىدا سەندەل ھىدى ۋە قۇرئان ئوقۇش ئاۋازى تارقالغان.","Etigenki budda ibadetxanisida sendel hidi we qur'an oqush awazi tarqalghan."]],"佳世客":[["佳世客是一家知名的连锁超市。","جاسكو تونۇلغان بىر زەنجىرسىمان بازار.","Jasko tonulghan bir zenjirsiman bazar."]],"依葫芦画瓢":[["别依葫芦画瓢，要创新。","كۆرگەننى قىلىپ باقماڭ، يېڭىلىق يارىتىڭ.","Körgenni qilip baqmang, yëngiliq yariting."]],"俗家":[["俗家弟子在修行中同样需要自律。","ئاممىۋى ئۆي ئەۋلادى ئىبادەتتەمۇ ئۆزىنى تىزگىنلەشكە موھتاج.","Ammiwi öy ewladi ibadettemu özini tizginleshke mohtaj."]],"保不住":[["这个秘密我保不住了。","بۇ سىرنى ئەمدى ساقلىيالمايمەن.","Bu sirni emdi saqliyalmaymen."]],"使领馆":[["使领馆为侨民提供领事服务。","ئەلچىلىك ۋە باش ئەلچىلىك چەت ئەلدىكى پۇقرالارغا كونسۇللىق مۇلازىمىتى تەمىنلەيدۇ.","Elchilik we bash elchilik chet eldiki puqralargha konsulliq mulazimiti teminleydu."]],"俏皮":[["他说起话来总是带着俏皮感。","ئۇ سۆزلىگەندە ھەمىشە چاقچاق ئارىلاشتۇرۇپ سۆزلەيدۇ.","U sözligende hemishe chaqchaq arilashturup sözleydu."]],"做错":[["他做错了这道题。","ئۇ بۇ سوئالغا خاتا جاۋاب بەردى.","U bu so'algha xata jawab berdi."]],"偏置":[["图像出现了明显的偏置。","تەسۋىردە كۆرۈنەرلىك ئېغىش پەيدا بولدى.","Teswirde körünerlik ëghish peyda boldi."]],"偷取":[["她偷取了他的秘密。","ئۇ ئۇنىڭ سىرىنى ئوغرىلىدى.","U uning sirini oghrilidi."]],"倡言":[["他倡言减少碳排放。","ئۇ كاربون ئاجرىتىشنى ئازايتىشنى تەشەببۇس قىلىدۇ.","U karbon ajritishni azaytishni teshebbus qilidu."]],"传感":[["这个传感器能检测温度变化。","بۇ سېنسور تېمپېراتۇرا ئۆزگىرىشىنى بايقىيالايدۇ.","Bu sënsor tëmpëratura özgirishini bayqiyalaydu."]],"催眠状态":[["她在催眠状态下完全放松。","ئۇ ھىپنوز ھالىتىدە پۈتۈنلەي بوشاشتى.","U hipnoz halitide pütünley boshashti."]],"像差":[["镜头存在轻微像差。","ئوبيېكتىپتا ئازغىنە ئوخشىماسلىق بار.","Obyëktipta azghine oxshimasliq bar."]],"伤患":[["这位伤患正在接受紧急治疗。","بۇ يارىدار جىددىي داۋالاش ئاستىدا.","Bu yaridar jiddiy dawalash astida."]],"倾尽":[["他倾尽一生守护这片土地。","ئۇ پۈتۈن ھاياتىنى بۇ زېمىننى قوغداشقا سەرپ قىلدى.","U pütün hayatini bu zëminni qoghdashqa serp qildi."]],"克隆人":[["克隆人引发了关于人类未来的争议。","كرىۋېتسا ئىنسان كەلگۈسى توغرىسىدا تالاش-تارتىشلارنى قوزغىدى.","Kriwëtsa insan kelgüsi toghrisida talash-tartishlarni qozghidi."]],"全体会议":[["全体会议现在开始。","ئومۇمىي يىغىن ھازىر باشلانسۇن.","Omumiy yighin hazir bashlansun."]],"克拉斯诺亚尔斯克":[["克拉斯诺亚尔斯克位于西伯利亚。","كراسنويارسك سىبىرىيەدە جايلاشقان.","Krasnoyarsk sibiriyede jaylashqan."]],"光禄大夫":[["光禄大夫是汉代设立的官位。","گۇاڭلۇ داداۋخەن خەن سۇلالىسى دەۋرىدە قۇرۇلغان ئەمەلدارلىق ئورنى.","Guanglu dadawxen xen sulalisi dewride qurulghan emeldarliq orni."]],"内伤":[["他因意外造成了严重的内伤。","ئۇ تاسادىپىي ھادىسە سەۋەبىدىن ئېغىر ئىچكى زەخىمەلەندى.","U tasadipiy hadise sewebidin ëghir ichki zeximelendi."]],"八一五":[["八一五事件是历史上的重要时刻。","بايىۋۇ ۋەقەسى تارىختىكى مۇھىم بىر پەيت.","Bayiwu weqesi tarixtiki muhim bir peyt."]],"公猫":[["公猫经常和母猫一起玩耍。","ئاممىۋى مۈشۈك ئانىلىق مۈشۈك بىلەن دائىم بىللە ئوينايدۇ.","Ammiwi müshük aniliq müshük bilen da'im bille oynaydu."]],"公毫":[["公毫是古代的一种货币单位。","ئاممىۋى مىللىمېتىر قەدىمكى زاماندىكى بىر خىل پۇل بىرلىكى ئىدى.","Ammiwi millimëtir qedimki zamandiki bir xil pul birliki idi."]],"冀县":[["冀县历史悠久。","جى ناھىيىسىنىڭ تارىخى ئۇزۇن.","Ji nahiyisining tarixi uzun."]],"册立":[["太子被正式册立。","شاھزادە رەسمىي ھالدا تەخت ۋارىسى قىلىپ بېكىتىلدى.","Shahzade resmiy halda text warisi qilip bëkitildi."]],"典型用途":[["该工具的典型用途是数据分析。","بۇ قورالنىڭ تىپىك ئىشلىتىلىشى سانلىق مەلۇمات تەھلىلى.","Bu qoralning tipik ishlitilishi sanliq melumat tehlili."]],"冒暑":[["他们冒暑坚持工作。","ئۇلار ئىسسىقتا چىداپ خىزمەت قىلىشنى داۋاملاشتۇردى.","Ular issiqta chidap xizmet qilishni dawamlashturdi."]],"冒险家":[["这位冒险家曾多次深入未知领域。","بۇ تەۋەككۈلچى سانائىتچى نۇرغۇن قېتىم نامەلۇم ساھەلەرگە چوڭقۇر كىرگەن.","Bu tewekkülchi sana'itchi nurghun qëtim namelum sahelerge chongqur kirgen."]],"共和党":[["共和党在选举中获胜。","جۇمھۇرىيەت پارتىيىسى سايلامدا غەلىبە قىلدى.","Jumhuriyet partiyisi saylamda ghelibe qildi."]],"出生日期":[["出生日期是1990年5月。","تۇغۇلغان ۋاقتى 1990-يىلى 5-ئاي.","Tughulghan waqti 1990-yili 5-ay."]],"分内":[["这是分内的工作，必须认真完成。","بۇ مېنىڭ ۋەزىپە دائىرىمدىكى خىزمەت، چوقۇم ئەستايىدىل تاماملىشىم كېرەك.","Bu mëning wezipe da'irimdiki xizmet, choqum estayidil tamamlishim kërek."]],"分包":[["分包合同需明确双方的责任。","تارماق ھۆددىگەرلىك توختامى ئىككى تەرەپنىڭ مەسئۇلىيىتىنى ئېنىق بەلگىلىشى كېرەك.","Tarmaq höddigerlik toxtami ikki terepning mes'uliyitini ëniq belgilishi kërek."]],"分担":[["大家应该共同分担责任。","ھەممەيلەن مەسئۇلىيەتنى ئورتاق ئۈستىگە ئېلىشى كېرەك.","Hemmeylen mes'uliyetni ortaq üstige ëlishi kërek."]],"分期付款":[["这家店支持分期付款。","بۇ دۇكان بۆلۈپ تۆلەش ئارقىلىق پۇل تۆلەشنى قوللايدۇ.","Bu dukan bölüp tölesh arqiliq pul töleshni qollaydu."]],"冰天雪地":[["冰天雪地里，一片寂静。","مۇز-قارلىق دۇنيادا، ھەممە يەر جىم-جىت.","Muz-qarliq dunyada, hemme yer jim-jit."]],"分锅":[["大家分锅做饭，分工明确。","ھەممەيلەن ئايرىم-ئايرىم قازاندا تاماق ئېتىپ، ئەمگەك تەقسىماتى ئېنىق.","Hemmeylen ayrim-ayrim qazanda tamaq ëtip, emgek teqsimati ëniq."]],"剧集":[["这部剧集很精彩。","بۇ تېلېۋىزىيە تىياتىرى ئىنتايىن ئاجايىپ.","Bu tëlëwiziye tiyatiri intayin ajayip."]],"创业精神":[["创业精神是成功的关键。","ئىگىلىك تىكلەش روھى مۇۋەپپەقىيەتنىڭ ئاچقۇچىدۇر.","Igilik tiklesh rohi muweppeqiyetning achquchidur."]],"划时代":[["这项技术堪称划时代的创新。","بۇ تېخنىكىنى دەۋر ئۆزگەرتىش يېڭىلىقى دېيىشكە بولىدۇ.","Bu tëxnikini dewr özgertish yëngiliqi dëyishke bolidu."]],"刘鹗":[["刘鹗是清代著名的小说家。","ليۇ ئې چىڭ سۇلالىسىنىڭ تانىمال رومانچىسى.","Lyu ë ching sulalisining tanimal romanchisi."]],"力挺":[["他力挺朋友，给予全力支持。","ئۇ دوستىنى كۈچ بىلەن قوللاپ، تولۇق مەدەت بەردى.","U dostini küch bilen qollap, toluq medet berdi."]],"勇武":[["古代将军以勇武著称。","قەدىمكى سەركەردىلەر باتۇرلۇقى بىلەن مەشھۇر ئىدى.","Qedimki serkerdiler baturluqi bilen meshhur idi."]],"包剪锤":[["我们来玩包剪锤吧！","كېلىڭ، تاش-قايچى-قەغەز ئويۇنىنى ئوينايلى!","Këling, tash-qaychi-qeghez oyunini oynayli!"]],"劝导":[["志愿者劝导人们保护环境。","پىدائىيلار كىشىلەرنى مۇھىتنى قوغداشقا نەسىھەت قىلدى.","Pida'iylar kishilerni muhitni qoghdashqa nesihet qildi."]],"劳改营":[["他曾在劳改营里度过多年。","ئۇ ئەمگەك ئىسلاھات لاگېرىدا كۆپ يىللارنى ئۆتكۈزدى.","U emgek islahat lagërida köp yillarni ötküzdi."]],"北方民族大学":[["北方民族大学历史悠久。","شىمال مىللەتلەر ئۇنىۋېرسىتېتىنىڭ تارىخى ئۇزۇن.","Shimal milletler uniwërsitëtining tarixi uzun."]],"北极光":[["北极光绚丽多彩。","شىمالىي قۇتۇپ نۇرى رەڭدار ۋە گۈزەل.","Shimaliy qutup nuri rengdar we güzel."]],"千锤百炼":[["经过千锤百炼，终成精品。","مىڭ قېتىم سوقۇلۇپ، مىڭ قېتىم چىنىقتۇرۇلۇپ، ئاخىرىدا ئالىي مەھسۇلاتقا ئايلاندى.","Ming qëtim soqulup, ming qëtim chiniqturulup, axirida aliy mehsulatqa aylandi."]],"南奥塞梯":[["南奥塞梯是俄罗斯联邦的一个自治共和国。","جەنۇبىي ئوسېتىيە رۇسىيە فېدېراتسىيەسىنىڭ بىر ئاپتونومىيەلىك جۇمھۇرىيىتى.","Jenubiy osëtiye rusiye fëdëratsiyesining bir aptonomiyelik jumhuriyiti."]],"南通市":[["南通市经济发达，交通便利。","نەنتۇڭ شەھىرىنىڭ ئىقتىسادى تەرەققىي قىلغان، قاتناشى قولايلىق.","Nentung shehirining iqtisadi tereqqiy qilghan, qatnashi qolayliq."]],"南极光":[["南极光是一种绚丽的大自然奇观。","جەنۇبىي قۇتۇپ نۇرى بىر خىل گۈزەل تەبىئەت مۆجىزىسى.","Jenubiy qutup nuri bir xil güzel tebi'et möjizisi."]],"北斗星":[["那颗北斗星格外明亮。","ئۇ بېيدۇ يۇلتۇزى ئالاھىدە يورۇقتۇر.","U bëydu yultuzi alahide yoruqtur."]],"博学多才":[["他博学多才，是位出色的学者。","ئۇ بىلىملىك ۋە كۆپ ئىقتىدارلىق، ئالاھىدە ئالىم.","U bilimlik we köp iqtidarliq, alahide alim."]],"占星":[["占星家通过星象预测运势。","مۇنەججىملەر يۇلتۇزلارنىڭ ھەرىكىتى ئارقىلىق تەقدىرنى مۆلچەرلەيدۇ.","Munejjimler yultuzlarning herikiti arqiliq teqdirni mölcherleydu."]],"卡尔加里":[["卡尔加里是加拿大阿尔伯塔省的首府。","كالگارى كانادانىڭ ئالبېرتا ئۆلكىسىنىڭ مەركىزى.","Kalgari kanadaning albërta ölkisining merkizi."]],"厄境":[["他陷入人生厄境。","ئۇ تۇرمۇشنىڭ قىيىن ئەھۋالىغا چۆكۈپ قالدى.","U turmushning qiyin ehwaligha chöküp qaldi."]],"厄娃":[["厄娃是神话人物。","ئېۋا مىفولوگىيەلىك شەخس.","Ëwa mifologiyelik shexs."]],"厄尔尼诺现象":[["厄尔尼诺现象频发。","ئېلنىنو ھادىسىسى كۆپ قېتىم يۈز بېرىدۇ.","Ëlnino hadisisi köp qëtim yüz bëridu."]],"厉目而视":[["老师用厉目而视的眼神警告学生不要扰乱课堂。","ئوقۇتقۇچى ئوقۇغۇچىلارنى رەھىمسىز نەزەر بىلەن قاراپ، دەرسخانىنى بۇزۇشماسلىققا ئاگاھلاندۇردى.","Oqutquchi oqughuchilarni rehimsiz nezer bilen qarap, dersxanini buzushmasliqqa agahlandurdi."]],"卡拉奇":[["卡拉奇是巴基斯坦的重要港口城市。","كاراچى پاكىستاننىڭ مۇھىم پورت شەھىرى.","Karachi pakistanning muhim port shehiri."]],"受制":[["他受制于复杂的规则。","ئۇ مۇرەككەپ قائىدىلەرگە بويسۇندۇرۇلغان.","U murekkep qa'idilerge boysundurulghan."]],"叫床":[["她早上被闹钟叫床。","ئۇ ئەتىگەندە ئاڭلىتىش سائىتى بىلەن ئويغاندى.","U etigende anglitish sa'iti bilen oyghandi."]],"可视化":[["数据可视化让信息更直观。","سانلىق مەلۇماتنى كۆرۈنەرلىك قىلىش ئۇچۇرنى تېخىمۇ بىۋاسىتە قىلىدۇ.","Sanliq melumatni körünerlik qilish uchurni tëximu biwasite qilidu."]],"可视电话":[["可视电话能实现面对面交流。","كۆرۈنەرلىك تېلېفون يۈزتۇرا سۆھبەتنى ئەمەلگە ئاشۇرالايدۇ.","Körünerlik tëlëfon yüztura söhbetni emelge ashuralaydu."]],"史前人":[["史前人生活在原始社会。","تارىختىن بۇرۇنقى ئىنسانلار ئىپتىدائىي جەمئىيەتتە ياشىغان.","Tarixtin burunqi insanlar iptida'iy jem'iyette yashighan."]],"同屋":[["同屋而居，彼此关照。","بىر ئۆيدە تۇرۇپ، بىر-بىرىگە كۆيۈنۈش كېرەك.","Bir öyde turup, bir-birige köyünüsh kërek."]],"吩坦尼":[["吩坦尼用于麻醉。","فېنتانىل ئانېستېزىيەدە ئىشلىتىلىدۇ.","Fëntanil anëstëziyede ishlitilidu."]],"合扇":[["他合扇表示结束。","ئۇ يەلپۈگۈچنى ياپقاندا ئاخىرلاشقانلىقنى بىلدۈردى.","U yelpügüchni yapqanda axirlashqanliqni bildürdi."]],"吴官正":[["吴官正曾任中央纪委副书记。","ۋۇ گۈەنجېڭ ئىلگىرى مەركىزىي تەفتىش كومىتېتىنىڭ مۇئاۋىن شۇجىسى بولغان.","Wu güenjëng ilgiri merkiziy teftish komitëtining mu'awin shujisi bolghan."]],"呈文":[["古代官员需通过呈文向皇帝汇报事务。","قەدىمكى زاماندىكى ئەمەلدارلار ئەرزنامە ئارقىلىق خەنزۇ ئىمپېراتورىغا ئىشلارنى مەلۇم قىلىشى كېرەك ئىدى.","Qedimki zamandiki emeldarlar erzname arqiliq xenzu impëratorigha ishlarni melum qilishi kërek idi."]],"吴王阖闾":[["吴王阖闾是吴国的开国君主。","ۋۇ پادىشاھ خېلۈي ۋۇ دۆلىتىنىڭ قۇرغۇچى ھۆكۈمدارى ئىدى.","Wu padishah xëlüy wu dölitining qurghuchi hökümdari idi."]],"周华健":[["周华健演唱过许多经典歌曲。","جوۋ خۇاجيەن نۇرغۇن كلاسسىك ناخشىلارنى ئېيتقان.","Jow xuajyen nurghun klassik naxshilarni ëytqan."]],"哈喇":[["哈喇子从他的嘴角流了下来。","ئۇنىڭ ئاغزىنىڭ چېتىدىن سىلەگەي ئېقىپ چۈشتى.","Uning aghzining chëtidin silegey ëqip chüshti."]],"哈努卡":[["哈努卡是犹太教的重大节日。","ھانۇكا يەھۇدى دىنىنىڭ مۇھىم بايرىمى.","Hanuka yehudi dinining muhim bayrimi."]],"咔嚓":[["树枝咔嚓一声断了。","شاخ شىقىلدەپ سۇنۇپ كەتتى.","Shax shiqildep sunup ketti."]],"员林":[["员林是台湾的一个小镇。","يۈەنلىن تەيۋەندىكى بىر كىچىك بازىرى.","Yüenlin teywendiki bir kichik baziri."]],"唐宋八大家":[["唐宋八大家是唐宋时期的八位著名文学家。","تاڭ-سۇڭ سەككىز ئۇستازى تاڭ-سۇڭ دەۋرىدىكى سەككىز داڭلىق ئەدىب.","Tang-sung sekkiz ustazi tang-sung dewridiki sekkiz dangliq edib."]],"商旅":[["商旅人员经常需要长途出差。","سودا سەپەر ئەھلىلىرى كۆپىنچە ئۇزۇن مۇساپىلىك سەپەرگە چىقىشى كېرەك.","Soda seper ehliliri köpinche uzun musapilik seperge chiqishi kërek."]],"哪儿跟哪儿":[["他说的话哪儿跟哪儿，根本听不懂。","ئۇنىڭ سۆزلىرى قەيەر بىلەن قەيەر، ئەسلا چۈشىنىش تەس.","Uning sözliri qeyer bilen qeyer, esla chüshinish tes."]],"喜力":[["他买了一瓶喜力啤酒。","ئۇ بىر بوتۇلكا خېنىكېن پىۋا سېتىۋالدى.","U bir botulka xënikën piwa sëtiwaldi."]],"喜幛":[["门上挂着喜庆的喜幛。","ئىشىككە خۇشاللىق تىلىكى بىلەن خۇشال پەردە ئېسىلغان.","Ishikke xushalliq tiliki bilen xushal perde ësilghan."]],"丧梆":[["丧梆是古代出殡时使用的乐器。","ماتەم چاۋىسى قەدىمكى زاماندا دەپنە مۇراسىمىدا ئىشلىتىلىدىغان چالغۇ ئەسۋابى.","Matem chawisi qedimki zamanda depne murasimida ishlitilidighan chalghu eswabi."]],"丧胆":[["敌人被我们的气势吓得丧胆。","دۈشمەن بىزنىڭ روھىي ھەيۋىمىزدىن قورقۇپ كەتتى.","Düshmen bizning rohiy heywimizdin qorqup ketti."]],"单源论":[["单源论解释物种起源。","يالغۇز مەنبە نەزەرىيەسى تۈرلەرنىڭ كېلىپ چىقىشىنى چۈشەندۈرىدۇ.","Yalghuz menbe nezeriyesi türlerning këlip chiqishini chüshendüridu."]],"嘴稳":[["他说话嘴稳不慌乱。","ئۇ سۆزلىگەندە ئاغزى مۇقىم، ئالدىراپ كەتمەيدۇ.","U sözligende aghzi muqim, aldirap ketmeydu."]],"吨级":[["这架飞机的吨级属于重型类别。","بۇ ئايروپىلاننىڭ توننا دەرىجىسى ئېغىر تىپقا تەۋە.","Bu ayropilanning tonna derijisi ëghir tipqa tewe."]],"哗然":[["他的发言引起了全场哗然。","ئۇنىڭ سۆزى مەيداندىكىلەرنىڭ ۋاراڭ-چۇرۇڭىنى قوزغىدى.","Uning sözi meydandikilerning warang-churungini qozghidi."]],"嗓子眼":[["他嗓子眼有点干，想喝水。","ئۇنىڭ تاماق ئۆتكىلى قۇرغاقلاپ، سۇ ئىچكىسى كەلدى.","Uning tamaq ötkili qurghaqlap, su ichkisi keldi."]],"四强":[["四强队伍在决赛中展开了激烈角逐。","تۆت كۈچلۈك كوماندا ھەل قىلغۇچ مۇسابىقىدە كەسكىن رىقابەت ئېلىپ باردى.","Töt küchlük komanda hel qilghuch musabiqide keskin riqabet ëlip bardi."]],"回绝":[["他礼貌地回绝了朋友的邀请。","ئۇ ئەدەبلىك بىلەن دوستىنىڭ تەكلىپىنى رەت قىلدى.","U edeblik bilen dostining teklipini ret qildi."]],"回话":[["他终于开口回话了。","ئۇ ئاخىرى ئېغىز ئېچىپ جاۋاب قايتۇردى.","U axiri ëghiz ëchip jawab qayturdi."]],"国际级":[["这项赛事达到了国际级水平。","بۇ مۇسابىقە خەلقئارا دەرىجىلىك سەۋىيەگە يەتتى.","Bu musabiqe xelq'ara derijilik sewiyege yetti."]],"图木舒克市":[["图木舒克市位于新疆南部。","تۇمشۇق شەھىرى شىنجاڭنىڭ جەنۇبىدا جايلاشقان.","Tumshuq shehiri shinjangning jenubida jaylashqan."]],"圆形面包":[["圆形面包是法国的特色。","يۇمىلاق بولكا فرانسىيەنىڭ ئالاھىدىلىكىدۇر.","Yumilaq bolka fransiyening alahidilikidur."]],"土库曼斯坦":[["土库曼斯坦位于中亚。","تۈركمەنىستان ئوتتۇرا ئاسىيادا جايلاشقان.","Türkmenistan ottura asiyada jaylashqan."]],"图解说明":[["图解说明让内容更易理解。","سىزمىلىق چۈشەندۈرۈش مەزمۇننى تېخىمۇ چۈشىنىشلىك قىلدى.","Sizmiliq chüshendürüsh mezmunni tëximu chüshinishlik qildi."]],"图灵奖":[["图灵奖是计算机领域的最高荣誉。","تۇرىڭ مۇكاپاتى كومپيۇتېر ساھەسىدىكى ئەڭ يۇقىرى شەرەپتۇر.","Turing mukapati kompyutër sahesidiki eng yuqiri shereptur."]],"坐像":[["坐像是指坐姿的雕像。","ئولتۇرۇش ھەيكىلى ئولتۇرۇش ھالىتىدىكى ھەيكەلنى كۆرسىتىدۇ.","Olturush heykili olturush halitidiki heykelni körsitidu."]],"埃及豆":[["埃及豆是一种营养价值很高的豆类作物。","مىسىر پۇرچىقى ئوزۇقلۇق قىممىتى ئىنتايىن يۇقىرى بىر خىل پۇرچاق تېرىقچىلىق زىرائىتى.","Misir purchiqi ozuqluq qimmiti intayin yuqiri bir xil purchaq tëriqchiliq zira'iti."]],"地积":[["地积指土地的面积和体积。","يەر كۆلىمى يەرنىڭ ئاۋدانى ۋە ھەجىمىنى كۆرسىتىدۇ.","Yer kölimi yerning awdani we hejimini körsitidu."]],"地西泮":[["地西泮是一种镇静药物。","دىيازېپام بىر خىل تىنچلاندۇرۇش دورىسى.","Diyazëpam bir xil tinchlandurush dorisi."]],"垂老":[["他垂老之际仍坚持工作。","ئۇ قېرىغان چېغىدىمۇ يەنىلا خىزمەت قىلىشنى داۋاملاشتۇردى.","U qërighan chëghidimu yenila xizmet qilishni dawamlashturdi."]],"垂头丧气":[["考试失败后，他垂头丧气地回家。","ئىمتىھاندىن مەغلۇپ بولغاندىن كېيىن، ئۇ باشىنى ساڭگىلىتىپ ئۆيگە قايتتى.","Imtihandin meghlup bolghandin këyin, u bashini sanggilitip öyge qaytti."]],"块状":[["呈块状的固体物质。","پارچە شەكىللىك قاتتىق ماددا.","Parche shekillik qattiq madda."]],"塔塔儿":[["塔塔儿人历史上曾建立汗国。","تاتارلار تارىختا خانلىق قۇرۇپ باققان.","Tatarlar tarixta xanliq qurup baqqan."]],"压力容器":[["压力容器需要定期检查安全状况。","بېسىم ئىدىشى بىخەتەرلىك ئەھۋالىنى قەرەللىك تەكشۈرتۈشكە موھتاج.","Bësim idishi bixeterlik ehwalini qerellik tekshürtüshke mohtaj."]],"壮语":[["壮语是壮族的官方语言。","جۇاڭ تىلى جۇاڭزۇ مىللىتىنىڭ رەسمىي تىلى.","Juang tili juangzu millitining resmiy tili."]],"多大点事":[["多大点事，别太在意。","قانچىلىك چوڭ ئىش ئەمەس، بەك كۆڭۈل بۆلمەڭ.","Qanchilik chong ish emes, bek köngül bölmeng."]],"多瑙":[["多瑙河是欧洲的一条重要河流。","دانۇب دەرياسى ياۋروپادىكى بىر مۇھىم دەريادۇر.","Danub deryasi yawropadiki bir muhim deryadur."]],"够朋友":[["关键时刻，他才够朋友。","ئاچقۇچلۇق پەيتتە ئاندىن ئۇ دوستلۇقنىڭ ھەققىنى بەردى.","Achquchluq peytte andin u dostluqning heqqini berdi."]],"大尾巴狼":[["大尾巴狼看起来很狡猾。","چوڭ قۇيرۇقلۇق بۆرە ئىنتايىن ھىيلىگەر كۆرۈنىدۇ.","Chong quyruqluq böre intayin hiyliger körünidu."]],"外科医生":[["外科医生技术高超。","تاشقى كېسەللىكلەر دوختۇرىنىڭ تېخنىكىسى يۇقىرى.","Tashqi kësellikler doxturining tëxnikisi yuqiri."]],"大篆":[["大篆是古代的一种文字。","داچۇەن قەدىمكى زاماندىكى بىر خىل يېزىقتۇر.","Dachuen qedimki zamandiki bir xil yëziqtur."]],"大红大紫":[["他事业大红大紫。","ئۇنىڭ ئىشلىرى چوڭ قىزىل ۋە چوڭ بىنەپشە.","Uning ishliri chong qizil we chong binepshe."]],"大摇大摆":[["他大摇大摆地走了。","ئۇ كۆركەم ھەرىكەت بىلەن مېڭىپ كەتتى.","U körkem heriket bilen mëngip ketti."]],"大放厥词":[["他大放厥词，令人反感。","ئۇ چوڭ گەپلەرنى قىلىپ، كىشىلەرنى بىزار قىلدى.","U chong geplerni qilip, kishilerni bizar qildi."]],"大雄宝殿":[["大雄宝殿是寺庙的主殿。","چوڭ بۇتخانا ئىبادەتخانىنىڭ باش زالىدۇر.","Chong butxana ibadetxanining bash zalidur."]],"天上掉馅饼":[["天上掉馅饼，让人惊喜不已。","ئاسماندىن پىتە چۈشسە، كىشىنى ھەيران قالدۇرىدۇ.","Asmandin pite chüshse, kishini heyran qalduridu."]],"天底下":[["天底下没有做不到的事。","ئاسمان ئاستىدا قىلغىلى بولمايدىغان ئىش يوق.","Asman astida qilghili bolmaydighan ish yoq."]],"天体物理学":[["天体物理学是研究宇宙天体的学科。","ئاسمان جىسىملىرى فىزىكىسى ئالەم ئاسمان جىسىملىرىنى تەتقىق قىلىدىغان پەندۇر.","Asman jisimliri fizikisi alem asman jisimlirini tetqiq qilidighan pendur."]],"天真烂漫":[["孩子们天真烂漫，充满朝气。","بالىلار ساددا ۋە گۈزەل بولۇپ، ھاياتىي كۈچكە تولغاندۇر.","Balilar sadda we güzel bolup, hayatiy küchke tolghandur."]],"天等县":[["天等县位于广西壮族自治区。","تيەندېڭ ناھىيىسى گۇاڭشى جۇاڭزۇ ئاپتونوم رايونىدا جايلاشقاندۇر.","Tyendëng nahiyisi guangshi juangzu aptonom rayonida jaylashqandur."]],"央中":[["央中公司发布了最新公告。","ياڭجوڭ شىركىتى ئەڭ يېڭى ئېلاننى ئېلان قىلدى.","Yangjong shirkiti eng yëngi ëlanni ëlan qildi."]],"奉旨":[["他奉旨前往边疆巡视。","ئۇ پەرمان بىلەن چېگرا رايونىغا تەكشۈرۈشكە باردى.","U perman bilen chëgra rayonigha tekshürüshke bardi."]],"太平门":[["太平门是古代城市的重要城门。","تىنچ ئوكيان دەرۋازىسى قەدىمكى شەھەرنىڭ مۇھىم دەرۋازىسى ئىدى.","Tinch okyan derwazisi qedimki sheherning muhim derwazisi idi."]],"大鳞大麻哈鱼":[["大鳞大麻哈鱼肉质鲜美。","چوڭ قاسراقلىق چوڭ ماخۇن بېلىقىنىڭ گۆشى تەملىك.","Chong qasraqliq chong maxun bëliqining göshi temlik."]],"契沙比克湾":[["契沙比克湾风景优美。","چېساپىك قولتۇقىنىڭ مەنزىرىسى گۈزەل.","Chësapik qoltuqining menzirisi güzel."]],"夹盘":[["服务员用夹盘端上了菜肴。","كۈتۈشكۈچى تەخسە بىلەن تاماقنى ئېلىپ كەلدى.","Kütüshküchi texse bilen tamaqni ëlip keldi."]],"套件":[["这个套件功能强大。","بۇ يۈرۈم ئىقتىدارى كۈچلۈك.","Bu yürüm iqtidari küchlük."]],"奢靡":[["这种奢靡之风不可取。","بۇنداق ئىسراپچىلىق روھىنى قوبۇل قىلغىلى بولمايدۇ.","Bundaq israpchiliq rohini qobul qilghili bolmaydu."]],"好胜":[["他性格好胜，总是想赢。","ئۇنىڭ خاراكتېرى غالىب كېلىشنى ياخشى كۆرىدۇ، دائىم يەڭگىسى كېلىدۇ.","Uning xaraktëri ghalib këlishni yaxshi köridu, da'im yenggisi këlidu."]],"如鲠在喉":[["这句话让他如鲠在喉，难以开口。","بۇ سۆز ئۇنىڭ بوغزىغا تىقىلىپ، ئېغىز ئاچالمىدى.","Bu söz uning boghzigha tiqilip, ëghiz achalmidi."]],"妄下雌黄":[["他妄下雌黄，随意修改历史记载。","ئۇ بىر تەرەپلىمە ھۆكۈم چىقىرىپ، تارىخىي خاتىرىلەرنى خالىغانچە ئۆزگەرتتى.","U bir tereplime höküm chiqirip, tarixiy xatirilerni xalighanche özgertti."]],"妮维娅":[["妮维娅是护肤品牌。","نىۋېيا تېرە ئاسراش ماركىسى.","Niwëya tëre asrash markisi."]],"妮维雅":[["妮维雅是知名化妆品。","نىۋېيا تونۇلغان گىرىم بۇيۇملىرى ماركىسى.","Niwëya tonulghan girim buyumliri markisi."]],"妲己":[["妲己是《封神演义》的角色。","داۋىي «فېڭشېن يانى» دىكى بىر رول.","Dawiy «fëngshën yani» diki bir rol."]],"姆巴巴内":[["姆巴巴内是南非城市。","مۇبابانې جەنۇبىي ئافرىقىدىكى بىر شەھەر.","Mubabanë jenubiy afriqidiki bir sheher."]],"如获至宝":[["他如获至宝，欣喜若狂。","ئۇ گويا خەزىنىگە ئېرىشكەندەك، خۇشاللىقىدىن ئۆزىنى تۇتالمىدى.","U goya xezinige ërishkendek, xushalliqidin özini tutalmidi."]],"娃娃生":[["娃娃生带来无限欢乐。","بالىلار رولى چەكسىز خۇشاللىق ئېلىپ كېلىدۇ.","Balilar roli cheksiz xushalliq ëlip këlidu."]],"威信县":[["这个县叫威信县。","بۇ ناھىيە ئابرۇي ناھىيىسى دەپ ئاتىلىدۇ.","Bu nahiye abruy nahiyisi dep atilidu."]],"娄星区":[["娄星区是娄底市的中心区。","لۇشىڭ رايونى لۇدى شەھىرىنىڭ مەركىزىي رايونى.","Lushing rayoni ludi shehirining merkiziy rayoni."]],"孤独症":[["孩子可能患有孤独症。","بالىدا يالغۇزلىق كېسىلى بولۇشى مۇمكىن.","Balida yalghuzliq kësili bolushi mumkin."]],"嫦娥":[["嫦娥奔月的故事广为流传。","چاڭئېنىڭ ئايغا ئۇچقان ھېكايىسى كەڭ تارقالغان.","Chang'ëning aygha uchqan hëkayisi keng tarqalghan."]],"守备":[["守备部队严密监控边境。","مۇداپىئە قىسمى ئەسكەرلىرى چېگرانى قاتتىق نازارەت قىلدى.","Mudapi'e qismi eskerliri chëgrani qattiq nazaret qildi."]],"孤雌生殖":[["这种生物可以通过孤雌生殖繁殖。","بۇ خىل جانلىق يالغۇز ئانىلىق كۆپىيىش ئارقىلىق كۆپىيەلەيدۇ.","Bu xil janliq yalghuz aniliq köpiyish arqiliq köpiyeleydu."]],"安地卡及巴布达":[["安地卡及巴布达是英联邦成员国。","ئانتىگۇئا ۋە باربۇدا بىرلەشمە مىللەتلەر تەشكىلاتىنىڭ ئەزاسىدۇر.","Antigu'a we barbuda birleshme milletler teshkilatining ezasidur."]],"宗主权":[["宗主权是宗主国的重要权利。","سۇزېرېنلىق ھوقۇقى سۇزېرېن دۆلەتنىڭ مۇھىم ھوقۇقىدۇر.","Suzërënliq hoquqi suzërën döletning muhim hoquqidur."]],"宣州区":[["宣州区是宣州的核心区域。","شۈەنجۇ رايونى شۈەنجۇنىڭ يادروسىدىكى رايون.","Shüenju rayoni shüenjuning yadrosidiki rayon."]],"客户服务部":[["客户服务部负责处理用户反馈。","ئابونتلار مۇلازىمەت بۆلۈمى ئىشلەتكۈچىلەرنىڭ ئىنكاسىنى بىر تەرەپ قىلىشقا مەسئۇل.","Abontlar mulazimet bölümi ishletküchilerning inkasini bir terep qilishqa mes'ul."]],"客满":[["餐厅今晚客满，需要预约才能入座。","رېستوران بۈگۈن كەچتە مېھمانلار بىلەن تولدى، ئورۇنغا ئولتۇرۇش ئۈچۈن ئالدىن كېلىشىش كېرەك.","Rëstoran bügün kechte mëhmanlar bilen toldi, orun'gha olturush üchün aldin këlishish kërek."]],"家电":[["新买的家电安装好了。","يېڭى سېتىۋېلىنغان ئائىلە ئېلېكتر سايمانلىرى قۇرۇلدى.","Yëngi sëtiwëlin'ghan a'ile ëlëktr saymanliri quruldi."]],"宿州":[["宿州是安徽省的一座城市。","سۇجۇ ئەنخۇي ئۆلكىسىدىكى بىر شەھەر.","Suju enxuy ölkisidiki bir sheher."]],"宁乡县":[["宁乡县盛产优质大米。","نىڭشياڭ ناھىيىسى ئېسىل گۈرۈچكە باي.","Ningshyang nahiyisi ësil gürüchke bay."]],"宠物门":[["宠物门事件引发热议。","ئەرمەك ھايۋان ئىشىكى ۋەقەسى قىزغىن مۇنازىرە قوزغىدى.","Ermek haywan ishiki weqesi qizghin munazire qozghidi."]],"家庭成员":[["家庭成员之间要互相尊重。","ئائىلە ئەزالىرى ئارىسىدا بىر-بىرىنى ھۆرمەتلەش كېرەك.","A'ile ezaliri arisida bir-birini hörmetlesh kërek."]],"尊奉":[["尊奉表示恭敬地服从。","زۇنفېڭ ھۆرمەت بىلەن بويسۇنۇشنى بىلدۈرىدۇ.","Zunfëng hörmet bilen boysunushni bildüridu."]],"尊师爱徒":[["尊师爱徒是良好的品德。","زۇنشى ئەي تۇ ېاخشى ئەخلاق.","Zunshi ey tu ëaxshi exlaq."]],"封神榜":[["《封神榜》是经典小说。","«فېڭشېنباڭ» كلاسسىك رومان.","«Fëngshënbang» klassik roman."]],"小亚细亚":[["小亚细亚历史久远。","كىچىك ئاسىيا تارىخى ئۇزۇن.","Kichik asiya tarixi uzun."]],"导读":[["导读帮助读者理解内容。","يېتەكچى ئوقۇش ئوقۇرمەنلەرگە مەزمۇننى چۈشىنىشكە ياردەم قىلىدۇ.","Yëtekchi oqush oqurmenlerge mezmunni chüshinishke yardem qilidu."]],"小儿经":[["这本小儿经很有名。","بۇ كىچىك بالىلار كىتابى بەك مەشھۇر.","Bu kichik balilar kitabi bek meshhur."]],"将帅":[["将帅的智慧决定战争的胜负。","جياڭشۇەينىڭ ئەقىل-پاراسىتى ئۇرۇشنىڭ غەلىبە-مەغلۇبىيىتىنى بەلگىلەيدۇ.","Jyangshueyning eqil-parasiti urushning ghelibe-meghlubiyitini belgileydu."]],"小厮":[["古代的小厮负责为主人跑腿办事。","قەدىمكى زاماندا كىچىك خىزمەتچى خوجايىنى ئۈچۈن يۈگۈرۈشۈپ ئىش قىلاتتى.","Qedimki zamanda kichik xizmetchi xojayini üchün yügürüshüp ish qilatti."]],"尥蹶子":[["马儿突然尥蹶子。","ئات تۇيۇقسىز چاقچىيىپ تەپتى.","At tuyuqsiz chaqchiyip tepti."]],"尼克森":[["尼克森是美国前总统。","نىكسون ئامېرىكىنىڭ سابىق پرېزىدېنتىدۇر.","Nikson amërikining sabiq prëzidëntidur."]],"小潮":[["小潮指的是海水的轻微涨落。","كىچىك ئوقيان دېگەن دېڭىز سۇيىنىڭ ئازغىنە كۆتۈرۈلۈشى ۋە چۆكۈشىنى كۆرسىتىدۇ.","Kichik oqyan dëgen dëngiz suyining azghine kötürülüshi we chöküshini körsitidu."]],"尖山区":[["尖山区位于城市北部。","جىيەنشەن رايونى شەھەرنىڭ شىمالىدا جايلاشقان.","Jiyenshen rayoni sheherning shimalida jaylashqan."]],"山子":[["山子是一种传统的木制玩具。","شەنزى ئەنئەنىۋى ياغاچ ئويۇنچۇق.","Shenzi en'eniwi yaghach oyunchuq."]],"尾羽":[["孔雀的尾羽色彩斑斓。","توسنىڭ قۇيرۇق پەيلىرى رەڭگارەڭ.","Tosning quyruq peyliri renggareng."]],"山毛榉":[["山毛榉是温带落叶树。","شاڭماۋجۈ مۆتىدىل بەلباغنىڭ يوپۇرماق تاشلايدىغان دەرىخىدۇر.","Shangmawjü mötidil belbaghning yopurmaq tashlaydighan derixidur."]],"居室":[["这个居室布置得很温馨。","بۇ ئۆي ئىنتايىن ئىللىق بېزەلگەن.","Bu öy intayin illiq bëzelgen."]],"岔道":[["这条岔道通向森林深处。","بۇ تارماق يول ئورماننىڭ چوڭقۇرىغا قاراپ بارىدۇ.","Bu tarmaq yol ormanning chongqurigha qarap baridu."]],"崇左":[["崇左是边境城市。","چوڭزو چېگرا شەھىرى.","Chongzo chëgra shehiri."]],"峰峰矿":[["峰峰矿资源丰富。","فېڭفېڭنىڭ مېنېرال بايلىقى مول.","Fëngfëngning mënëral bayliqi mol."]],"嵖岈山":[["嵖岈山是国家级风景名胜区。","چاياشەن دۆلەت دەرىجىلىك مەنزىرە رايونى.","Chayashen dölet derijilik menzire rayoni."]],"巡逻船":[["巡逻船在边境水域执行任务。","دورا كېمىسى چېگرا سۇ رايونىدا ۋەزىپە ئىجرا قىلدى.","Dora këmisi chëgra su rayonida wezipe ijra qildi."]],"工具箱":[["工具箱里放着各种工具。","قورال ساندۇقى ئىچىدە ھەر خىل قوراللار ساقلىنىدۇ.","Qoral sanduqi ichide her xil qorallar saqlinidu."]],"左营":[["左营是古代的军事营地。","سول لاگېر قەدىمكى زاماندىكى ھەربىي لاگېر ئىدى.","Sol lagër qedimki zamandiki herbiy lagër idi."]],"已作故人":[["我们已作故人，无需多言。","بىز ئاللىبۇرۇن ئۆتكەن دوستلاردىن بولدۇق، كۆپ سۆزلەشنىڭ ھاجىتى يوق.","Biz alliburun ötken dostlardin bolduq, köp sözleshning hajiti yoq."]],"巫蛊":[["巫蛊是一种古老的诅咒方式。","ۋۇگۇ قەدىمىي بىر خىل قارغىش ئۇسۇلى.","Wugu qedimiy bir xil qarghish usuli."]],"巴豆树":[["巴豆树的果实常被用作药材。","كروتون دەرىخىنىڭ مېۋىسى كۆپىنچە دورا ماتېرىيالى سۈپىتىدە ئىشلىتىلىدۇ.","Kroton derixining mëwisi köpinche dora matëriyali süpitide ishlitilidu."]],"市场价":[["市场价通常高于出厂价。","بازار باھاسى ئادەتتە زاۋۇت باھاسىدىن يۇقىرى.","Bazar bahasi adette zawut bahasidin yuqiri."]],"市政府":[["市政府负责管理城市的日常事务。","شەھەر ھۆكۈمىتى شەھەرنىڭ كۈندىلىك ئىشلىرىنى باشقۇرۇشقا مەسئۇل.","Sheher hökümiti sheherning kündilik ishlirini bashqurushqa mes'ul."]],"布氏苇莺":[["布氏苇莺是一种小型的鸟类。","بۇرچېلل تىلىق چىۋىقىن كىچىك قۇشلارنىڭ بىر تۈرىدۇر.","Burchëll tiliq chiwiqin kichik qushlarning bir türidur."]],"布琼布拉":[["布琼布拉是卢旺达的首都。","بۇجۇمبۇرا رۇئاندانىڭ پايتەختىدۇر.","Bujumbura ru'andaning paytextidur."]],"布里坦尼":[["布里坦尼是一位才华横溢的艺术家。","بۇرىتتانى ئىقتىدارلىق بىر سەنئەتكار.","Burittani iqtidarliq bir sen'etkar."]],"常德":[["常德是一座历史名城。","چاڭدې بىر تارىخىي داڭلىق شەھەردۇر.","Changdë bir tarixiy dangliq sheherdur."]],"带来":[["好消息给我们带来惊喜。","ياخشى خەۋەر بىزگە سۈرپرىز قىلدى.","Yaxshi xewer bizge sürpriz qildi."]],"幕间":[["幕间休息时，观众可以自由走动。","ئارىلىق ئارامىدا تاماشىبىنلار ئەركىن يۈرەلەيدۇ.","Ariliq aramida tamashibinlar erkin yüreleydu."]],"年较差":[["年较差用于比较年度数据差异。","يىللىق پەرق يىللىق سانلىق مەلۇمات پەرقىنى سېلىشتۇرۇشقا ئىشلىتىلىدۇ.","Yilliq perq yilliq sanliq melumat perqini sëlishturushqa ishlitilidu."]],"年关":[["年关临近，大家都忙碌起来。","يىل ئاخىرى يېقىنلاشقاندا، ھەممەيلەن ئالدىراش بولۇپ كېتىدۇ.","Yil axiri yëqinlashqanda, hemmeylen aldirash bolup këtidu."]],"店家":[["店家对顾客非常友好。","دۇكاندار خېرىدارلارغا ئىنتايىن ئىللىق مۇئامىلە قىلدى.","Dukandar xëridarlargha intayin illiq mu'amile qildi."]],"底蕴":[["这座古城深厚的文化底蕴令人向往。","بۇ قەدىمىي شەھەرنىڭ چوڭقۇر مەدەنىيەت ئاساسى كىشىنى ئىنتىلگۈدەك قىلىدۇ.","Bu qedimiy sheherning chongqur medeniyet asasi kishini intilgüdek qilidu."]],"度日":[["他每天度日如年，过得十分艰难。","ئۇ ھەر كۈنى بىر يىلدەك ئۆتكۈزىدۇ، ناھايىتى قىيىنچىلىق بىلەن ياشايدۇ.","U her küni bir yildek ötküzidu, nahayiti qiyinchiliq bilen yashaydu."]],"座上客":[["这位座上客是公司的贵宾。","بۇ ئولتۇرۇشلۇق مېھمان شىركەتنىڭ مۇھىم مېھمىنىدۇر.","Bu olturushluq mëhman shirketning muhim mëhminidur."]],"广州":[["广州是中国南方重要的经济中心。","گۇاڭجۇ جۇڭگونىڭ جەنۇبىدىكى مۇھىم ئىقتىساد مەركىزىدۇر.","Guangju junggoning jenubidiki muhim iqtisad merkizidur."]],"引柴":[["他引柴生火，准备晚餐。","ئۇ كېسەك يېقىپ ئوت ياقتى ۋە كەچلىك تاماق تەييارلىدى.","U kësek yëqip ot yaqti we kechlik tamaq teyyarlidi."]],"后母":[["后母对继子十分严厉。","ئۆگەي ئانا ئۆگەي ئوغلىغا ئىنتايىن قاتتىق مۇئامىلە قىلدى.","Ögey ana ögey oghligha intayin qattiq mu'amile qildi."]],"强身健体":[["太极拳是一种强身健体的运动。","تەيجىچۈەن بەدەننى كۈچلەندۈرىدىغان بىر خىل تەنتەربىيە ھەرىكىتىدۇر.","Teyjichüen bedenni küchlendüridighan bir xil tenterbiye herikitidur."]],"强迫性性行为":[["强迫性性行为可能源于心理因素。","مەجبۇرىيەت خاراكتېرلىك جىنسىي قىلمىشلار پىسخىكا ئامىللىرىدىن كېلىپ چىقىشى مۇمكىن.","Mejburiyet xaraktërlik jinsiy qilmishlar pisxika amilliridin këlip chiqishi mumkin."]],"徒刑":[["他被判了三年徒刑。","ئۇ ئۈچ يىللىق قاماق جازاسىغا ھۆكۈم قىلىندى.","U üch yilliq qamaq jazasigha höküm qilindi."]],"徐福":[["徐福是秦代著名的航海家。","شۈفۇ چىن سۇلالىسى دەۋرىنىڭ داڭلىق دېڭىز سەيياھى.","Shüfu chin sulalisi dewrining dangliq dëngiz seyyahi."]],"后进先出":[["后进先出是栈的基本操作原则。","ئارقىدىن كىرگەن ئالدىن چىقىدۇ، بۇ ستېكنىڭ ئاساسىي مەشغۇلات پرىنسىپى.","Arqidin kirgen aldin chiqidu, bu stëkning asasiy meshghulat prinsipi."]],"从母":[["孩子随母姓，称为从母。","بالا ئانىسىنىڭ فامىلىسىنى ئالىدۇ، بۇ ئانا تەرەپ دەپ ئاتىلىدۇ.","Bala anisining familisini alidu, bu ana terep dep atilidu."]],"德化":[["德化以精美的陶瓷工艺著称。","دېخۇا نەپىس فارفور ھۈنەر-سەنئىتى بىلەن تونۇلغان.","Dëxua nepis farfor hüner-sen'iti bilen tonulghan."]],"忍冬":[["这种忍冬花可以用来泡茶。","بۇ خىل ئۇچقۇن گۈلىدىن چاي دەملەپ ئىچكىلى بولىدۇ.","Bu xil uchqun gülidin chay demlep ichkili bolidu."]],"心广体胖":[["心广体胖，福气满满。","كۆڭلى كەڭ بولسا بەدەن سەمىرىدۇ، بەخت-سائادەت تولۇپ تاشىدۇ.","Köngli keng bolsa beden semiridu, bext-sa'adet tolup tashidu."]],"徽帜":[["徽帜是徽州的象征性旗帜。","خۇيجى خۇيجۇنىڭ سىمۋوللۇق بايرىقى.","Xuyji xuyjuning simwolluq bayriqi."]],"徽菜":[["徽菜是中国八大菜系之一。","خۇي تائاملىرى جۇڭگونىڭ سەككىز چوڭ تائام تۈرىنىڭ بىرى.","Xuy ta'amliri junggoning sekkiz chong ta'am türining biri."]],"恐高症":[["恐高症让他无法登山。","ئېگىزلىكتىن قورقۇش ئۇنىڭ تاغقا چىقىشىغا توسالغۇ بولدى.","Ëgizliktin qorqush uning taghqa chiqishigha tosalghu boldi."]],"性细胞":[["性细胞是繁殖后代的基本单位。","جىنسىي ھۈجەيرە ئەۋلاد قالدۇرۇشنىڭ ئاساسىي بىرلىكىدۇر.","Jinsiy hüjeyre ewlad qaldurushning asasiy birlikidur."]],"恩师":[["这位恩师教导我多年，恩情难忘。","بۇ مەرھەمەتلىك ئۇستاز ماڭا كۆپ يىل تەلىم بەردى، مەرھەمىتى ئۇنتۇلغۇسىز.","Bu merhemetlik ustaz manga köp yil telim berdi, merhemiti untulghusiz."]],"恩慈":[["他的恩慈之心，感染了所有人。","ئۇنىڭ مېھىر-شەپقەتلىك قەلبى ھەممەيلەنگە تەسىر قىلدى.","Uning mëhir-shepqetlik qelbi hemmeylen'ge tesir qildi."]],"悍马":[["那辆悍马越野车性能十分强大。","ئۇ ھاممېر تىپلىق تاغ ماشىنىسىنىڭ ئىقتىدارى ئىنتايىن كۈچلۈك.","U hammër tipliq tagh mashinisining iqtidari intayin küchlük."]],"急性阑尾炎":[["急性阑尾炎若不及时处理，可能危及生命。","ئۆتكۈر ئاپپېندىسىت ۋاقتىدا داۋالىنىمىسا، ھاياتقا خەۋپ يەتكۈزۈشى مۇمكىن.","Ötkür appëndisit waqtida dawalinimisa, hayatqa xewp yetküzüshi mumkin."]],"急诊室":[["他受伤后，被送往了急诊室。","ئۇ يارىلانغاندىن كېيىن جىددىي داۋالاش ئۆيىگە ئەۋەتىلدى.","U yarilan'ghandin këyin jiddiy dawalash öyige ewetildi."]],"愚拙":[["他言语愚拙，但心地善良。","ئۇنىڭ سۆزى ئەخمىقانە، لېكىن كۆڭلى ياخشى.","Uning sözi exmiqane, lëkin köngli yaxshi."]],"愚蒙":[["他愚蒙无知，难以教导。","ئۇ نادان، ئوقۇتۇشقا قىيىن.","U nadan, oqutushqa qiyin."]],"惆怅":[["他独自坐在窗边，满脸惆怅。","ئۇ يالغۇز ئۆزى دېرىزە بويىدا ئولتۇراتتى، چىرىدا قايغۇ ئېنىق كۆرۈنەتتى.","U yalghuz özi dërize boyida olturatti, chirida qayghu ëniq körünetti."]],"惨剧":[["火灾中的惨剧令人揪心。","ئوت ئاپىتىدىكى پاجىئە كىشىنىڭ يۈرىكىنى ئېچىشتۇرىدۇ.","Ot apitidiki paji'e kishining yürikini ëchishturidu."]],"爱情喜剧":[["这部电影是一部经典的爱情喜剧。","بۇ كىنو كلاسسىك مۇھەببەت كومېدىيىسىدۇر.","Bu kino klassik muhebbet komëdiyisidur."]],"爱乐":[["爱乐乐团经常举办音乐会。","ئايلىە ئوركېسترى دائىم مۇزىكا كېچىلىكى ئۆتكۈزىدۇ.","Aylie orkëstri da'im muzika këchiliki ötküzidu."]],"庆尚道":[["庆尚道是韩国的传统区域。","چىڭشاڭ يولى كورېيەنىڭ ئەنئەنىۋى رايونىدۇر.","Chingshang yoli korëyening en'eniwi rayonidur."]],"忆苦思甜":[["忆苦思甜，珍惜当下生活。","ئاچچىقنى ئەسكەرتىپ، تاتلىقنى ئويلاپ، ھازىرقى تۇرمۇشنى قەدرلەش كېرەك.","Achchiqni eskertip, tatliqni oylap, hazirqi turmushni qedrlesh kërek."]],"成名作":[["他的成名作广受好评。","ئۇنىڭ داڭق چىقارغان ئەسىرى كەڭ ئالقىشقا ئېرىشتى.","Uning dangq chiqarghan esiri keng alqishqa ërishti."]],"戈尔巴乔夫":[["戈尔巴乔夫推动了苏联的改革。","گوربېچېۋ سوۋېت ئىتتىپاقىنىڭ ئىسلاھاتىنى ئىلگىرى سۈردى.","Gorbëchëw sowët ittipaqining islahatini ilgiri sürdi."]],"戊戌变法":[["戊戌变法推动了中国的近代化进程。","پېنتاۋ ئىسلاھاتى جۇڭگونىڭ زامانىۋىلىشىش جەريانىنى ئىلگىرى سۈردى.","Pëntaw islahati junggoning zamaniwilishish jeryanini ilgiri sürdi."]],"或多或少":[["这件事他或多或少知道一些。","بۇ ئىش توغرىسىدا ئۇ ئازدىن-كۆپتىن بىلىدۇ.","Bu ish toghrisida u azdin-köptin bilidu."]],"戏侮":[["他的话带有戏侮的意味。","ئۇنىڭ سۆزلىرى مەسخىرە مەنىسىنى ئۆز ئىچىگە ئالىدۇ.","Uning sözliri mesxire menisini öz ichige alidu."]],"戴安娜王妃":[["戴安娜王妃深受民众爱戴。","دىئانا پادىشاھ ئايالى خەلق تەرىپىدىن چوڭقۇر ھۆرمەتكە سازاۋەر ئىدى.","Di'ana padishah ayali xelq teripidin chongqur hörmetke sazawer idi."]],"房玄龄":[["房玄龄是唐朝著名宰相。","فاڭ شيۈەنلىڭ تاڭ سۇلالىسىنىڭ مەشھۇر ۋەزىرى ئىدى.","Fang shyüenling tang sulalisining meshhur weziri idi."]],"打前站":[["他先打前站，再谈正事。","ئۇ ئالدى بىلەن ئالدىنقى ئورۇننى تەييارلايدۇ، ئاندىن ئەمەلىي ئىش توغرىسىدا سۆزلىشىدۇ.","U aldi bilen aldinqi orunni teyyarlaydu, andin emeliy ish toghrisida sözlishidu."]],"打吊瓶":[["她正在医院打吊瓶。","ئۇ دوختۇرخانىدا ئىنفۇزىيە ئېلىۋاتىدۇ.","U doxturxanida infuziye ëliwatidu."]],"托勒密王":[["托勒密王统治埃及。","پتولېمىي پادىشاھ مىسىرنى ئىدارە قىلغان.","Ptolëmiy padishah misirni idare qilghan."]],"扯谎":[["他编故事来扯谎。","ئۇ ھېكايە ئويدۇرۇپ يالغان سۆزلەيدۇ.","U hëkaye oydurup yalghan sözleydu."]],"成像":[["相机的成像效果非常出色。","كامېرانىڭ تەسۋىر ھاسىل قىلىش ئۈنۈمى ئىنتايىن ئالاھىدە.","Kamëraning teswir hasil qilish ünümi intayin alahide."]],"拉拉队":[["拉拉队为球队加油。","مەدەنىيەت كوماندىسى كوماندا ئۈچۈن ئورۇنلاشتى.","Medeniyet komandisi komanda üchün orunlashti."]],"把脉":[["医生通过把脉诊断病情。","دوختۇر تومۇر تۇتۇش ئارقىلىق كېسەللىكنى دىئاگنوز قىلىدۇ.","Doxtur tomur tutush arqiliq kësellikni di'agnoz qilidu."]],"找抽":[["他这样说话，简直找抽。","ئۇ بۇنداق سۆزلىسە، پۈتۈنلەي ئۇرۇلۇشنى تەلەپ قىلغانلىق.","U bundaq sözlise, pütünley urulushni telep qilghanliq."]],"拈指":[["他拈指间完成了复杂的动作。","ئۇ بارماقلىرى ئارىسىدا مۇرەككەپ ھەرىكەتنى تاماملىدى.","U barmaqliri arisida murekkep heriketni tamamlidi."]],"扒屋牵牛":[["他们扒屋牵牛，准备搬家。","ئۇلار ئۆينى سۆكۈپ كالا يېتىلەپ، كۆچۈشكە تەييارلىق قىلدى.","Ular öyni söküp kala yëtilep, köchüshke teyyarliq qildi."]],"批发价":[["批发价远低于零售价格。","توپ سېتىش باھاسى پارچە سېتىش باھاسىدىن ئىنتايىن ئەرزان.","Top sëtish bahasi parche sëtish bahasidin intayin erzan."]],"拍马":[["他拍马溜须。","ئۇ يالاقزادەلىك قىلىدۇ.","U yalaqzadelik qilidu."]],"拉法赫":[["拉法赫是挪威的一座城市。","لافاھېك نورۋېگىيەنىڭ بىر شەھىرى.","Lafahëk norwëgiyening bir shehiri."]],"招人":[["这家店很招人喜欢。","بۇ دۇكان كىشىلەرگە بەك ياقىدۇ.","Bu dukan kishilerge bek yaqidu."]],"拉票":[["他在积极拉票争取支持。","ئۇ ئاكتىپلارچە بېلەت تارتىپ قوللاش ئىزدەۋاتىدۇ.","U aktiplarche bëlet tartip qollash izdewatidu."]],"拳棒":[["他用拳棒击退了敌人的进攻。","ئۇ مۇشت ۋە تاياق بىلەن دۈشمەننىڭ ھۇجۇمىنى قايتۇردى.","U musht we tayaq bilen düshmenning hujumini qayturdi."]],"拼读":[["老师教学生如何正确拼读单词。","ئوقۇتقۇچى ئوقۇغۇچىلارغا سۆزلەرنى توغرا ئىملا ئوقۇشنى ئۆگىتىدۇ.","Oqutquchi oqughuchilargha sözlerni toghra imla oqushni ögitidu."]],"拜佛":[["每天清晨，她都会去寺庙拜佛。","ھەر كۈنى ئەتىگەندە ئۇ ئىبادەتخانىغا بېرىپ بۇتخانىغا چوقۇنىدۇ.","Her küni etigende u ibadetxanigha bërip butxanigha choqunidu."]],"拼死":[["他拼死也要保护家人。","ئۇ ئۆلۈمگە تەۋەككۈل قىلىپمۇ ئائىلىسىنى قوغدايدۇ.","U ölümge tewekkül qilipmu a'ilisini qoghdaydu."]],"拿撒勒":[["拿撒勒是耶稣的出生地。","ناسارە ئىيسانىڭ تۇغۇلغان جايى.","Nasare iysaning tughulghan jayi."]],"拿办":[["官员被拿办后受审。","ئەمەلدار تۇتۇلغاندىن كېيىن سوتلاندى.","Emeldar tutulghandin këyin sotlandi."]],"指甲剪":[["指甲剪可以修剪指甲形状。","تىرناق قىسقۇچ تىرناق شەكلىنى تۈزىتەلەيدۇ.","Tirnaq qisquch tirnaq sheklini tüziteleydu."]],"捕头":[["捕头带领队伍破案。","تۇتقۇن باشلىق ئەترەتنى يېتەكلەپ ئىشنى ئاچتى.","Tutqun bashliq etretni yëteklep ishni achti."]],"扫把":[["扫把用来扫地。","سۈپۈرگە يەر سۈپۈرۈشكە ئىشلىتىلىدۇ.","Süpürge yer süpürüshke ishlitilidu."]],"掖咕":[["他偷偷掖咕着东西。","ئۇ ئەستايىدىللىق بىلەن نەرسىلەرنى يوشۇرۇپ قويدى.","U estayidilliq bilen nersilerni yoshurup qoydi."]],"排水管":[["更换老旧的排水管。","كونا سۇ چىقىرىش تۇرۇبىسىنى ئالماشتۇرۇڭ.","Kona su chiqirish turubisini almashturung."]],"掰扯":[["别掰扯了，直接解决问题吧。","تالاش-تارتىش قىلماي، مەسىلىنى بىۋاسىتە ھەل قىلايلى.","Talash-tartish qilmay, mesilini biwasite hel qilayli."]],"揉磨":[["经过揉磨，他变得更成熟。","ئۇۋۇلاش-سىلاش ئارقىلىق ئۇ تېخىمۇ يېتىلدى.","Uwulash-silash arqiliq u tëximu yëtildi."]],"挟细拿粗":[["他挟细拿粗，最终自食其果。","ئۇ ئىنچىكىنى تۇتقۇن قىلىپ تومنى ئالدى، ئاخىرىدا ئۆزى ئاقىۋىتىگە قالدى.","U inchikini tutqun qilip tomni aldi, axirida özi aqiwitige qaldi."]],"掰弯":[["这根铁丝被用力掰弯了。","بۇ تۆمۈر سىم كۈچ بىلەن ئېگىلدى.","Bu tömür sim küch bilen ëgildi."]],"撑腰":[["他勇敢地为我们撑腰。","ئۇ بىز ئۈچۈن مەردانىلىك بىلەن ئارقا تىرەك بولدى.","U biz üchün merdanilik bilen arqa tirek boldi."]],"撒网":[["渔民开始撒网捕鱼。","بېلىقچىلار تور تاشلاپ بېلىق تۇتۇشقا باشلىدى.","Bëliqchilar tor tashlap bëliq tutushqa bashlidi."]],"撒切尔":[["撒切尔是英国前首相。","تاتچېر بىرلەشمە پادىشاھلىقنىڭ سابىق باش مىنىستىرى.","Tatchër birleshme padishahliqning sabiq bash ministiri."]],"摩天大厦":[["这座摩天大厦非常壮观。","بۇ ئاسمان-بىنا ئىنتايىن ھەيۋەتلىك.","Bu asman-bina intayin heywetlik."]],"擦枪走火":[["这把枪不小心擦枪走火了。","بۇ مىلتىق ئېھتىياتسىزلىقتىن سۈرتۈلۈپ ئوق چىقىرىۋەتتى.","Bu miltiq ëhtiyatsizliqtin sürtülüp oq chiqiriwetti."]],"拨乱反正":[["他努力拨乱反正，恢复秩序。","ئۇ قالايمىقانچىلىقنى تۈزىتىپ، تەرتىپنى ئەسلىگە كەلتۈرۈشكە تىرىشتى.","U qalaymiqanchiliqni tüzitip, tertipni eslige keltürüshke tirishti."]],"据情办理":[["需据情办理，灵活应对。","ئەھۋالغا قاراپ بىر تەرەپ قىلىش، ئەۋرىشىم مۇئامىلە قىلىش كېرەك.","Ehwalgha qarap bir terep qilish, ewrishim mu'amile qilish kërek."]],"收兵":[["军队开始收兵回营。","ئارمىيە ئەسكەرلەرنى چېكىندۈرۈپ لاگېرغا قايتۇرۇشنى باشلىدى.","Armiye eskerlerni chëkindürüp lagërgha qayturushni bashlidi."]],"故交":[["多年未见的故交突然来访。","كۆپ يىللاردىن بېرى كۆرۈشمىگەن كونا دوستى تۇيۇقسىز كېلىپ قالدى.","Köp yillardin bëri körüshmigen kona dosti tuyuqsiz këlip qaldi."]],"敬酒不吃吃罚酒":[["敬酒不吃吃罚酒，后果自负！","ھاراق ئىچمىسەڭ جازا ئىچىسەن، ئاقىۋىتىگە ئۆزۈڭ مەسئۇل!","Haraq ichmiseng jaza ichisen, aqiwitige özüng mes'ul!"]],"敌手":[["他的敌手实力不容小觑。","ئۇنىڭ رەقىبىنىڭ كۈچىنى كەمسىتىشكە بولمايدۇ.","Uning reqibining küchini kemsitishke bolmaydu."]],"文献学":[["文献学研究古籍的整理与考证。","ھۆججەتشۇناسلىق قەدىمكى كىتابلارنى رەتلەش ۋە تەكشۈرۈشنى تەتقىق قىلىدۇ.","Höjjetshunasliq qedimki kitablarni retlesh we tekshürüshni tetqiq qilidu."]],"文旦":[["文旦是一种口感清甜的柑橘。","ۋېندەن تاتلىق تەملىك بىر خىل پورتاكال.","Wënden tatliq temlik bir xil portakal."]],"文武":[["文武兼备是理想的人才。","ھەم ئەدەبىي ھەم ھەربىي جەھەتتە تولۇق بولۇش ئىدېئال ئىستىداتتۇر.","Hem edebiy hem herbiy jehette toluq bolush idë'al istidattur."]],"斑胁姬鹛":[["斑胁姬鹛在林间跳跃觅食。","تاغ تېكىسى يان قۇشى ئورمان ئارىسىدا سەكرەپ يېمەك ئىزدەيدۇ.","Tagh tëkisi yan qushi orman arisida sekrep yëmek izdeydu."]],"斯大林":[["斯大林是苏联历史上的重要领导人。","ستالىن سوۋېت ئىتتىپاقى تارىخىدىكى مۇھىم رەھبەر.","Stalin sowët ittipaqi tarixidiki muhim rehber."]],"新成土":[["这片新成土适合种植作物。","بۇ يېڭى شەكىللەنگەن تۇپراق زىرائەت تېرىشقا ماس كېلىدۇ.","Bu yëngi shekillen'gen tupraq zira'et tërishqa mas këlidu."]],"新港":[["新港是一个繁忙的港口城市。","شىنگاڭ ئاۋات پورت شەھىرى.","Shin'gang awat port shehiri."]],"文不加点":[["这篇古文文不加点，堪称典范。","بۇ قەدىمىي ئەسەر ھېچقانداق تۈزىتىشسىز يېزىلغان، ئۈلگە دېيىشكە بولىدۇ.","Bu qedimiy eser hëchqandaq tüzitishsiz yëzilghan, ülge dëyishke bolidu."]],"文化城":[["文化城内有许多艺术展览。","مەدەنىيەت شەھىرىدە نۇرغۇن سەنئەت كۆرگەزمىلىرى بار.","Medeniyet shehiride nurghun sen'et körgezmiliri bar."]],"新丰县":[["新丰县位于山区。","شىنفېڭ ناھىيىسى تاغلىق رايوندا جايلاشقان.","Shinfëng nahiyisi taghliq rayonda jaylashqan."]],"新田县":[["新田县以丰富的矿产资源闻名。","يېڭتيەن ناھىيىسى مول كان بايلىقلىرى بىلەن داڭلىق.","Yëngtyen nahiyisi mol kan bayliqliri bilen dangliq."]],"断背":[["他们断背多年。","ئۇلار كۆپ يىللاردىن بۇيان ئۈزۈلگەن مۇناسىۋەتتە.","Ular köp yillardin buyan üzülgen munasiwette."]],"于雾霭之中":[["他于雾霭之中隐约看见身影。","ئۇ تۇمان ئىچىدە سىلۇېتنى تۇتۇق كۆردى.","U tuman ichide siluëtni tutuq kördi."]],"既往不咎":[["他既往不咎，原谅了你的过错。","ئۇ ئۆتكەن ئىشنى سورىمىدى، سېنىڭ خاتالىقىڭنى كەچۈردى.","U ötken ishni sorimidi, sëning xataliqingni kechürdi."]],"昂仁":[["昂仁的景色令人惊叹。","ئاڭرىننىڭ مەنزىرىسى كىشىنى ھەيران قالدۇرىدۇ.","Angrinning menzirisi kishini heyran qalduridu."]],"早先":[["早先这里是一片森林。","ئىلگىرى بۇ يەر ئورمانلىق ئىدى.","Ilgiri bu yer ormanliq idi."]],"明十三陵":[["明十三陵是明朝皇帝的陵墓。","مىڭ سۇلالىسىنىڭ ئون ئۈچ مازارى مىڭ سۇلالىسى ئىمپېراتورلىرىنىڭ مازارىدۇر.","Ming sulalisining on üch mazari ming sulalisi impëratorlirining mazaridur."]],"明智之举":[["这是明智之举。","بۇ ئەقىللىق بىر ھەرىكەت.","Bu eqilliq bir heriket."]],"明武宗":[["明武宗在位期间推行多项改革。","مىڭ ۋۇزۇڭ ھۆكۈمرانلىق قىلغان مەزگىلدە كۆپلىگەن ئىسلاھاتلارنى ئىلگىرى سۈردى.","Ming wuzung hökümranliq qilghan mezgilde köpligen islahatlarni ilgiri sürdi."]],"星冰乐":[["他点了一杯星冰乐来解渴。","ئۇ ئۇسسۇزلىقىنى قاندۇرۇش ئۈچۈن بىر ئىستاكان يۇلتۇز مۇز قەھۋىسى بۇيرۇتتى.","U ussuzliqini qandurush üchün bir istakan yultuz muz qehwisi buyrutti."]],"星图":[["星图展示了各个星体的位置。","يۇلتۇز خەرىتىسى ھەر خىل يۇلتۇز جىسىملىرىنىڭ ئورنىنى كۆرسىتىدۇ.","Yultuz xeritisi her xil yultuz jisimlirining ornini körsitidu."]],"昵比":[["这个昵比游戏很有趣。","بۇ يېقىنلىق ئويۇنى بەك قىزىقارلىق.","Bu yëqinliq oyuni bek qiziqarliq."]],"时不时":[["他时不时会想起往事。","ئۇ ۋاقتى-ۋاقتىدا ئۆتمۈشلەرنى ئەسلىگە ئالىدۇ.","U waqti-waqtida ötmüshlerni eslige alidu."]],"普氏野马":[["普氏野马生活在草原上。","پۇشى يەبەي ئېتى يايلاقتا ياشايدۇ.","Pushi yebey ëti yaylaqta yashaydu."]],"普通鹰鹃":[["普通鹰鹃喜欢在树上筑巢。","ئادەتتىكى قىرغىي كاككۇكى دەرەخلەردە ئۇۋا ياساشنى ياخشى كۆرىدۇ.","Adettiki qirghiy kakkuki derexlerde uwa yasashni yaxshi köridu."]],"普遍性假设":[["普遍性假设需要进一步验证。","ئومۇمىيلىق پەرەزىنى تېخىمۇ تەكشۈرۈش كېرەك.","Omumiyliq perezini tëximu tekshürüsh kërek."]],"智多星":[["他是个智多星，总能出主意。","ئۇ ئەقىللىق يۇلتۇز، ھەمىشە چارە تېپەلەيدۇ.","U eqilliq yultuz, hemishe chare tëpeleydu."]],"书报":[["他喜欢看报纸和书报。","ئۇ گېزىت ۋە كىتاب-ژۇرناللارنى ئوقۇشنى ياخشى كۆرىدۇ.","U gëzit we kitab-zhurnallarni oqushni yaxshi köridu."]],"最惠国待遇":[["最惠国待遇促进国际贸易。","ئەڭ ئىمتىيازلىق دۆلەت مۇئامىلىسى خەلقئارا سودىنى ئىلگىرى سۈرىدۇ.","Eng imtiyazliq dölet mu'amilisi xelq'ara sodini ilgiri süridu."]],"月全食":[["月全食令人惊叹。","ئاي تولۇق تۇتۇلۇش ھەيران قالدۇرىدۇ.","Ay toluq tutulush heyran qalduridu."]],"有生之年":[["希望有生之年能亲眼见证这一幕。","ھايات ۋاقتىمدا بۇ مەنزىرىنى ئۆز كۆزۈم بىلەن كۆرۈشنى ئۈمىد قىلىمەن.","Hayat waqtimda bu menzirini öz közüm bilen körüshni ümid qilimen."]],"有魅力":[["她很有魅力，吸引很多人。","ئۇ ناھايىتى جەلپكار، كۆپ كىشىلەرنى جەلپ قىلىدۇ.","U nahayiti jelpkar, köp kishilerni jelp qilidu."]],"服硬":[["他决定服硬，坚持己见。","ئۇ قەتئىي تەرسالىق قىلىشنى قارار قىلدى، ئۆز پىكرىدە چىڭ تۇردى.","U qet'iy tersaliq qilishni qarar qildi, öz pikride ching turdi."]],"有毅力":[["有毅力的人才能坚持到底。","ئىرادىلىك كىشىلەرلا ئاخىرغىچە چىداپ تۇرالايدۇ.","Iradilik kishilerla axirghiche chidap turalaydu."]],"朝鲜日报":[["《朝鲜日报》是朝鲜的重要报纸。","«چاۋشيەن كۈندىلىك گېزىتى» چاۋشيەننىڭ مۇھىم گېزىتى.","«Chawshyen kündilik gëziti» chawshyenning muhim gëziti."]],"有声书":[["她喜欢听有声书来放松自己。","ئۇ ئۆزىنى بوشاشتۇرۇش ئۈچۈن ئاۋازلىق كىتابلارنى ئاڭلاشنى ياخشى كۆرىدۇ.","U özini boshashturush üchün awazliq kitablarni anglashni yaxshi köridu."]],"有的放矢":[["他的批评有的放矢，切中要害。","ئۇنىڭ تەنقىدى نىشانلىق بولۇپ، ئاچقۇچلۇق نۇقتىغا تەگدى.","Uning tenqidi nishanliq bolup, achquchluq nuqtigha tegdi."]],"未老先衰":[["他未老先衰。","ئۇ قېرىمىغان تۇرۇپ قېرىپ قالدى.","U qërimighan turup qërip qaldi."]],"札幌":[["札幌是日本北海道的首府城市。","ساپپورو ياپونىيەنىڭ خوككايدو ئۆلكىسىنىڭ مەركىزىي شەھىرى.","Sapporo yaponiyening xokkaydo ölkisining merkiziy shehiri."]],"李嘉诚":[["李嘉诚是著名的商人。","لى كا شىڭ تانىلغان سودىگەر.","Li ka shing tanilghan sodiger."]],"朱子":[["朱子是宋代著名的理学家。","جۇ زى سۇڭ سۇلالىسى دەۋرىنىڭ تانىلغان نەزەرىيەشۇناسى.","Ju zi sung sulalisi dewrining tanilghan nezeriyeshunasi."]],"本士":[["本士是古代对本地居民的称呼。","بېنشى قەدىمكى زاماندا يەرلىك ئاھالىلەرگە قارىتىلغان ئاتالغۇ.","Bënshi qedimki zamanda yerlik ahalilerge qaritilghan atalghu."]],"东君":[["东君象征春天，带来生机。","دۇڭجۈن باھارنى سىمۋول قىلىدۇ، ھاياتلىق ئېلىپ كېلىدۇ.","Dungjün baharni simwol qilidu, hayatliq ëlip këlidu."]],"东施效颦":[["东施效颦，结果反而更丑。","شەرقىي شى خەنزۇ ئايالنىڭ تەقلىد قىلىشى نەتىجىدە تېخىمۇ سەت كۆرۈندى.","Sherqiy shi xenzu ayalning teqlid qilishi netijide tëximu set köründi."]],"东北亚":[["东北亚包括中国、日本和韩国。","شەرقىي شىمالىي ئاسىيا جۇڭگو، ياپونىيە ۋە كورېيەنى ئۆز ئىچىگە ئالىدۇ.","Sherqiy shimaliy asiya junggo, yaponiye we korëyeni öz ichige alidu."]],"东瀛":[["东瀛一词常用来指代日本。","دۇڭيىڭ دېگەن سۆز كۆپىنچە ياپونىيەنى كۆرسىتىش ئۈچۈن ئىشلىتىلىدۇ.","Dungying dëgen söz köpinche yaponiyeni körsitish üchün ishlitilidu."]],"枇杷膏":[["枇杷膏可以缓解咳嗽症状。","بىۋا مېيى يۆتەل ئالامەتلىرىنى يېنىكلىتەلەيدۇ.","Biwa mëyi yötel alametlirini yënikliteleydu."]],"板滞":[["他的表情板滞，显得毫无生气。","ئۇنىڭ چىرايى تاختا بولۇپ، ھېچقانداق جانلىقلىق كۆرۈنمەيدۇ.","Uning chirayi taxta bolup, hëchqandaq janliqliq körünmeydu."]],"柔道":[["他每天练习柔道以增强体能。","ئۇ ھەر كۈنى جۇدو مەشىق قىلىپ، جىسمانىي كۈچىنى ئاشۇرىدۇ.","U her küni judo meshiq qilip, jismaniy küchini ashuridu."]],"柄权":[["柄权即权力。","بىڭچۈەن دەل ھوقۇق.","Bingchüen del hoquq."]],"柳青":[["柳青是一位著名的民间艺术家。","ليۇچىڭ مەشھۇر بىر خەلق سەنئەتكارى.","Lyuching meshhur bir xelq sen'etkari."]],"柴鱼片":[["柴鱼片常用于制作高汤。","دىزېل بېلىق پارچىسى كۆپىنچە شورپا تەييارلاشقا ئىشلىتىلىدۇ.","Dizël bëliq parchisi köpinche shorpa teyyarlashqa ishlitilidu."]],"核苷":[["核苷是核酸的基本组成单位。","نۇكلېئوزىد يادرو كىسلاتاسىنىڭ ئاساسىي تەركىبىي بىرلىكىدۇر.","Nuklë'ozid yadro kislatasining asasiy terkibiy birlikidur."]],"柳宗元":[["柳宗元是唐代著名的文学家，他的散文和诗歌广为流传。","ليۇ زوڭيۈەن تاڭ سۇلالىسى دەۋرىدىكى مەشھۇر ئەدىب بولۇپ، ئۇنىڭ نەسرى ۋە شېئىرلىرى كەڭ تارقالغان.","Lyu zongyüen tang sulalisi dewridiki meshhur edib bolup, uning nesri we shë'irliri keng tarqalghan."]],"果如所料":[["事情的发展果如所料。","ئىشنىڭ تەرەققىياتى مېغىز ئويلىغاندەك بولدى.","Ishning tereqqiyati mëghiz oylighandek boldi."]],"果洛":[["果洛位于青海省的西部。","گوولو چىڭخەي ئۆلكىسىنىڭ غەربىي قىسمىدا جايلاشقان.","Goolo chingxey ölkisining gherbiy qismida jaylashqan."]],"果洛州":[["果洛州以畜牧业闻名。","گوولو ئوبلاستى چارۋىچىلىق بىلەن داڭلىق.","Goolo oblasti charwichiliq bilen dangliq."]],"桐庐县":[["桐庐县位于浙江省的东部。","تۇڭلۇ ناھىيىسى جېجياڭ ئۆلكىسىنىڭ شەرقىي قىسمىدا جايلاشقان.","Tunglu nahiyisi jëjyang ölkisining sherqiy qismida jaylashqan."]],"桐柏":[["桐柏山是著名的道教名山。","تۇڭبەي تېغى مەشھۇر داۋىزم نامىدىكى تاغ.","Tungbey tëghi meshhur dawizm namidiki tagh."]],"格式塔疗法":[["格式塔疗法帮助人们自我认知。","گېشتالت داۋالاش ئۇسۇلى كىشىلەرگە ئۆزىنى تونۇشقا ياردەم بېرىدۇ.","Gështalt dawalash usuli kishilerge özini tonushqa yardem bëridu."]],"棒子国":[["棒子国的传统美食深受游客喜爱。","كورىيەنىڭ ئەنئەنىۋى تائاملىرى ساياھەتچىلەرنىڭ ياقتۇرۇشىغا ئېرىشتى.","Koriyening en'eniwi ta'amliri sayahetchilerning yaqturushigha ërishti."]],"棒棒腿":[["这道棒棒腿外酥里嫩。","بۇ تاياقسىمان پۇت تاشقىسى قىتىر، ئىچى يۇمشاق.","Bu tayaqsiman put tashqisi qitir, ichi yumshaq."]],"棕腹林鸲":[["棕腹林鸲喜欢在森林中活动。","قوڭۇر قورساقلىق ئورمان بۇلبۇلى ئورماندا پائالىيەت قىلىشنى ياخشى كۆرىدۇ.","Qongur qorsaqliq orman bulbuli ormanda pa'aliyet qilishni yaxshi köridu."]],"棕腹蓝仙鹟":[["棕腹蓝仙鹟的羽毛呈蓝色。","قوڭۇر قورساقلىق كۆك پەرى قۇشىنىڭ پەيلىرى كۆك رەڭدە.","Qongur qorsaqliq kök peri qushining peyliri kök rengde."]],"业龙":[["业龙品牌广受好评。","يېلۇڭ ماركىسى كەڭ كۆلەمدە ياخشى باھاغا ئېرىشتى.","Yëlung markisi keng kölemde yaxshi bahagha ërishti."]],"枪崩":[["枪崩导致多人受伤。","ئوق ئېتىش نۇرغۇن كىشىلەرنىڭ يارىلىنىشىغا سەۋەب بولدى.","Oq ëtish nurghun kishilerning yarilinishigha seweb boldi."]],"乐平市":[["乐平市以丰富的矿产资源著称。","لېپىڭ شەھىرى باي مىنېرال بايلىقلىرى بىلەن داڭلىق.","Lëping shehiri bay minëral bayliqliri bilen dangliq."]],"楼主":[["楼主分享了很多经验。","بەننىڭ ئىگىسى نۇرغۇن تەجرىبىلەرنى ئورتاقلاشتى.","Benning igisi nurghun tejribilerni ortaqlashti."]],"概要":[["请提供报告的简要概要。","دوكلاتنىڭ قىسقىچە خۇلاسىسىنى تەمىنلەڭ.","Doklatning qisqiche xulasisini teminleng."]],"橄榄绿":[["橄榄绿是一种经典颜色。","زەيتۇن يېشىل ئەنئەنىۋى رەڭ.","Zeytun yëshil en'eniwi reng."]],"机油":[["定期检查机油能延长发动机寿命。","مايىل ماينى قەرەللىك تەكشۈرۈش ماتورنىڭ ئۆمرىنى ئۇزارتىدۇ.","Mayil mayni qerellik tekshürüsh matorning ömrini uzartidu."]],"横截线":[["这条线是横截线。","بۇ سىزىق كۆندىلەڭ كېسىش سىزىقى.","Bu siziq köndileng kësish siziqi."]],"横钩":[["毛笔的横钩写法需要技巧。","مەۋىي قەلىمنىڭ كۆندەلەڭ ئىلمىكى يېزىش ئۇسۇلى ماھارەت تەلەپ قىلىدۇ.","Mewiy qelimning köndeleng ilmiki yëzish usuli maharet telep qilidu."]],"检测仪":[["检测仪能准确测量温度变化。","تەكشۈرۈش ئەسۋابى تېمپېراتۇرا ئۆزگىرىشىنى توغرا ئۆلچەيەلەيدۇ.","Tekshürüsh eswabi tëmpëratura özgirishini toghra ölcheyeleydu."]],"枪闩":[["枪闩卡住后，武器暂时无法发射。","مىلتىق زاپچاسى قىستىلىپ قالغاندىن كېيىن، قورال ۋاقىتلىق ئوق ئېتالمايدۇ.","Miltiq zapchasi qistilip qalghandin këyin, qoral waqitliq oq ëtalmaydu."]],"杠龟":[["杠龟是一种罕见的爬行动物。","گاڭگۈي ئاز ئۇچرايدىغان بىر خىل ئۆمىلىگۈچى ھايۋاندۇر.","Ganggüy az uchraydighan bir xil ömiligüchi haywandur."]],"台灯":[["台灯的光线柔和，适合夜间阅读。","ئۈستەل چىرىغىنىڭ نۇرى يۇمشاق بولۇپ، كېچىدە ئوقۇشقا ماس كېلىدۇ.","Üstel chirighining nuri yumshaq bolup, këchide oqushqa mas këlidu."]],"正经八百":[["他说话正经八百。","ئۇ جىددىي ئەھۋالدا سۆزلەيدۇ.","U jiddiy ehwalda sözleydu."]],"步人后尘":[["他步人后尘，重蹈覆辙。","ئۇ باشقىلارنىڭ ئىزىدىن مېڭىپ، ئوخشاش خاتالىقنى قايتا سادى.","U bashqilarning izidin mëngip, oxshash xataliqni qayta sadi."]],"武安市":[["武安市以铁矿资源著称。","ۋۇئەن شەھىرى تۆمۈر مەدەنىيەت بايلىقى بىلەن تونۇلغان.","Wu'en shehiri tömür medeniyet bayliqi bilen tonulghan."]],"武侠小说":[["他最近开始阅读武侠小说。","ئۇ يېقىندا ۋۇشيا رومانلىرىنى ئوقۇشنى باشلىدى.","U yëqinda wushya romanlirini oqushni bashlidi."]],"正如":[["正如大家所料，比赛结果很精彩。","ھەممەيلەن كۈتكەندەك، مۇسابىقە نەتىجىسى ئىنتايىن مەرگەنلىك.","Hemmeylen kütkendek, musabiqe netijisi intayin mergenlik."]],"死囚":[["死囚被关在特殊的牢房中。","ئۆلۈمگە ھۆكۈم قىلىنغان مەھبۇس ئالاھىدە قاماقخانىغا سولاندى.","Ölümge höküm qilin'ghan mehbus alahide qamaqxanigha solandi."]],"死定":[["他这次死定了，无法逃脱。","ئۇ بۇ قېتىم ئۆلۈمگە مەھكۇم، قېچىپ قۇتۇلالمايدۇ.","U bu qëtim ölümge mehkum, qëchip qutulalmaydu."]],"正式投票":[["正式投票将在明天举行。","رەسمىي بېلەت تاشلاش ئەتە ئېلىپ بېرىلىدۇ.","Resmiy bëlet tashlash ete ëlip bërilidu."]],"归纳推理":[["归纳推理是从个别到一般的思维方法。","ئىندۇكسىيەلىك خۇلاسە ئايرىملىقتىن ئومۇمىيلىققا قاراپ پىكىر قىلىش ئۇسۇلىدۇر.","Induksiyelik xulase ayrimliqtin omumiyliqqa qarap pikir qilish usulidur."]],"母犬":[["母犬负责照顾幼崽。","ئانا ئىت كۈچۈكلىرىنى بېقىشقا مەسئۇل.","Ana it küchüklirini bëqishqa mes'ul."]],"每日镜报":[["《每日镜报》报道了最新的科技进展。","«كۈندىلىك ئەينەك گېزىتى» ئەڭ يېڭى پەن-تېخنىكا تەرەققىياتىنى خەۋەر قىلدى.","«Kündilik eynek gëziti» eng yëngi pen-tëxnika tereqqiyatini xewer qildi."]],"归向":[["他的归向是追求真理与正义。","ئۇنىڭ يۆنىلىشى ھەقىقەت ۋە ئادالەتنى ئىزدەش.","Uning yönilishi heqiqet we adaletni izdesh."]],"毛诞节":[["毛诞节是重要的节日。","خام تۇغۇلغان كۈن مۇھىم بىر بايرام.","Xam tughulghan kün muhim bir bayram."]],"民意测验":[["民意测验显示多数人支持改革。","خەلق پىكرى سىناقى كۆپچىلىكنىڭ ئىسلاھاتنى قوللايدىغانلىقىنى كۆرسەتتى.","Xelq pikri sinaqi köpchilikning islahatni qollaydighanliqini körsetti."]],"残冬腊月":[["残冬腊月里，天气格外寒冷。","قىش ئاخىرلاشقان چىللە ئېيىدا، ھاۋا بەك سوغۇق ئىدى.","Qish axirlashqan chille ëyida, hawa bek soghuq idi."]],"歼击":[["战斗机在空中歼击敌机。","جەڭچى ئايروپىلان ھاۋادا دۈشمەن ئايروپىلانىنى ئۇردى.","Jengchi ayropilan hawada düshmen ayropilanini urdi."]],"毛刺":[["衣服上的毛刺需要修剪。","كىيىمدىكى تۈكلەرنى كېسىپ تازىلاش كېرەك.","Kiyimdiki tüklerni kësip tazilash kërek."]],"比手划脚":[["他比手划脚地解释着。","ئۇ قول-پۇتلىرى بىلەن ئىشارەت قىلىپ چۈشەندۈردى.","U qol-putliri bilen isharet qilip chüshendürdi."]],"民丰":[["民丰地区农业发达。","مىنفېڭ رايونىنىڭ يېزا ئىگىلىكى تەرەققىي قىلغان.","Minfëng rayonining yëza igiliki tereqqiy qilghan."]],"永德":[["永德县地处云南省西南部。","يۇڭدې ناھىيىسى يۈننەن ئۆلكىسىنىڭ جەنۇبىي غەربىدە جايلاشقان.","Yungdë nahiyisi yünnen ölkisining jenubiy gherbide jaylashqan."]],"江达":[["江达是一个历史悠久的地方。","جياڭدا ئۇزۇن تارىخقا ئىگە بىر جاي.","Jyangda uzun tarixqa ige bir jay."]],"气道":[["气道畅通是呼吸健康的关键。","نەپەس يولىنىڭ ئوچۇق بولۇشى نەپەس ساغلاملىقىنىڭ ئاچقۇچى.","Nepes yolining ochuq bolushi nepes saghlamliqining achquchi."]],"汀线":[["这条汀线风景优美。","بۇ تىڭشەننىڭ مەنزىرىسى گۈزەل.","Bu tingshenning menzirisi güzel."]],"沙家浜":[["沙家浜是革命老区。","شاجياباڭ بىر ئىنقىلابىي كونا رايون.","Shajyabang bir inqilabiy kona rayon."]],"汕头":[["汕头是广东的历史名城。","شېنتوۋ گۇاڭدۇڭنىڭ تارىخىي شەھىرى.","Shëntow guangdungning tarixiy shehiri."]],"沙司":[["这款沙司搭配烤肉非常美味。","بۇ خىل سوس قوي كاۋىپى بىلەن ناھايىتى تەملىك.","Bu xil sos qoy kawipi bilen nahayiti temlik."]],"河外星系":[["河外星系距离我们非常遥远。","دەريا سىرتىدىكى گالاكتىكىلار بىزدىن ئىنتايىن يىراق.","Derya sirtidiki galaktikilar bizdin intayin yiraq."]],"法向力":[["法向力指向圆心方向。","قانۇن يۆنىلىشلىك كۈچ چەمبەر مەركىزى يۆنىلىشىگە قارايدۇ.","Qanun yönilishlik küch chember merkizi yönilishige qaraydu."]],"求证":[["科学结论需要反复求证。","ئىلمىي خۇلاسىنى قايتا-قايتا ئىسپاتلاش كېرەك.","Ilmiy xulasini qayta-qayta ispatlash kërek."]],"波荡":[["湖面泛起轻微的波荡。","كۆل يۈزىدە يېنىك دولقۇنلار پەيدا بولماقتا.","Köl yüzide yënik dolqunlar peyda bolmaqta."]],"波隆那":[["波隆那是一座历史名城。","بولونيا تارىخىي داڭلىق شەھەر.","Bolonya tarixiy dangliq sheher."]],"法院裁决":[["法院裁决此案由被告承担责任。","سوت مەھكىمىسى بۇ ئىشنى جاۋابكار تەرەپنىڭ مەسئۇلىيەت ئۈستىگە ئېلىشىغا ھۆكۈم قىلدى.","Sot mehkimisi bu ishni jawabkar terepning mes'uliyet üstige ëlishigha höküm qildi."]],"法鲁克":[["法鲁克是埃及的前国王。","فارۇق مىسىرنىڭ ئىلگىرىكى پادىشاھى.","Faruq misirning ilgiriki padishahi."]],"泛论":[["他对各种社会问题都发表泛论。","ئۇ ھەر خىل جەمئىيەت مەسىلىلىرى توغرىسىدا ئومۇمىي مۇھاكىمە يۈرگۈزدى.","U her xil jem'iyet mesililiri toghrisida omumiy muhakime yürgüzdi."]],"法源寺":[["法源寺是京城历史悠久的古刹之一。","فايۈەن ئىبادەتخانىسى پايتەختنىڭ ئۇزۇن تارىخلىق قەدىمكى ئىبادەتخانىلىرىنىڭ بىرى.","Fayüen ibadetxanisi paytextning uzun tarixliq qedimki ibadetxanilirining biri."]],"洛基":[["洛基是北欧神话中的神。","لوكى شىمالىي ياۋروپا ئەپسانىلىرىدىكى بىر تەڭرىدۇر.","Loki shimaliy yawropa epsaniliridiki bir tengridur."]],"流量明星":[["这位流量明星的粉丝数量惊人。","بۇ ئىنترېت يۇلتۇزىنىڭ مەستانىلىرىنىڭ سانى ھەيران قالارلىق.","Bu intrët yultuzining mestanilirining sani heyran qalarliq."]],"洱源":[["洱源以独特的少数民族文化著称。","ئېريۈەن ئۆزگىچە ئاز سانلىق مىللەت مەدەنىيىتى بىلەن تونۇلغان.","Ëryüen özgiche az sanliq millet medeniyiti bilen tonulghan."]],"消息队列":[["消息队列用于处理异步通信任务。","خەۋەر ئۆچرىتى ئاسىنخرون ئالاقە ۋەزىپىلىرىنى بىر تەرەپ قىلىشقا ئىشلىتىلىدۇ.","Xewer öchriti asinxron alaqe wezipilirini bir terep qilishqa ishlitilidu."]],"涿州":[["涿州是河北省的历史名城。","جوجۇ خېبېي ئۆلكىسىنىڭ تارىخىي مەشھۇر شەھىرى.","Joju xëbëy ölkisining tarixiy meshhur shehiri."]],"淘洗":[["衣服需要仔细淘洗。","كىيىملەرنى ئەستايىدىل يۇيۇش كېرەك.","Kiyimlerni estayidil yuyush kërek."]],"深明大义":[["她深明大义，不计较个人得失。","ئۇ چوڭ ئادالەتنى چوڭقۇر چۈشىنىپ، شەخسىي پايدا-زىياننى ھېسابقا ئالمايدۇ.","U chong adaletni chongqur chüshinip, shexsiy payda-ziyanni hësabqa almaydu."]],"淋漓尽致":[["他在表演中将角色的情感表现得淋漓尽致。","ئۇ ئويۇندا رولنىڭ ھېسسىياتىنى تولۇق جارى قىلدۇردى.","U oyunda rolning hëssiyatini toluq jari qildurdi."]],"清淤":[["河道清淤工作正在进行中。","ئۆستەڭنى لەي-لايىدىن تازىلاش خىزمىتى داۋاملىشىۋاتىدۇ.","Östengni ley-layidin tazilash xizmiti dawamlishiwatidu."]],"清汤":[["清汤味道鲜美。","سۇلۇق شورپا تەملىك.","Suluq shorpa temlik."]],"清涤":[["清涤是一种清洁方法。","چىڭدى تازىلاش ئۇسۇلى.","Chingdi tazilash usuli."]],"渡渡鸟":[["渡渡鸟是已灭绝的鸟类。","دودو قۇشى يوقىلىپ كەتكەن قۇشلارنىڭ بىرىدۇر.","Dodo qushi yoqilip ketken qushlarning biridur."]],"消费器件":[["手机是常见的消费器件。","يانفون كۆپ ئۇچرايدىغان ئىستېمال زاپچاسى.","Yanfon köp uchraydighan istëmal zapchasi."]],"淌下":[["泪水从他的眼角缓缓淌下，滴在地板上。","كۆز يېشى ئۇنىڭ كۆز قىرلىرىدىن ئاستا ئېقىپ، پولغا تامدى.","Köz yëshi uning köz qirliridin asta ëqip, polgha tamdi."]],"淬火":[["钢铁经过淬火后更加坚硬。","پولات سۇغىرىلغاندىن كېيىن تېخىمۇ قاتتىق بولىدۇ.","Polat sughirilghandin këyin tëximu qattiq bolidu."]],"湮灭":[["恒星最终会湮灭消失。","تۇراقلىق يۇلتۇزلار ئاخىرىدا يوقىلىپ كېتىدۇ.","Turaqliq yultuzlar axirida yoqilip këtidu."]],"凑数":[["他只是为了凑数而来。","ئۇ پەقەت سان تولدۇرۇش ئۈچۈنلا كەلدى.","U peqet san toldurush üchünla keldi."]],"准确性":[["实验结果具有很高的准确性。","تەجرىبە نەتىجىسى ئىنتايىن يۇقىرى ئېنىقلىققا ئىگە.","Tejribe netijisi intayin yuqiri ëniqliqqa ige."]],"温体肉":[["温体肉是烹饪中常用的食材。","ئىللىق گۆش تاماق ئېتىشتە كۆپ ئىشلىتىلىدىغان يېمەكلىك ماتېرىيالىدۇر.","Illiq gösh tamaq ëtishte köp ishlitilidighan yëmeklik matëriyalidur."]],"温泉县":[["温泉县拥有丰富的地热资源。","ئىسسىق بۇلاق ناھىيىسى باي گېئوتېرمال بايلىققا ئىگە.","Issiq bulaq nahiyisi bay gë'otërmal bayliqqa ige."]],"渔鼓":[["渔鼓是传统乐器的一种。","بېلىق دۇمبىقى ئەنئەنىۋى چالغۇ ئەسۋابلىرىنىڭ بىر تۈرىدۇر.","Bëliq dumbiqi en'eniwi chalghu eswablirining bir türidur."]],"满腹经纶":[["这位学者满腹经纶，对古代文学研究颇深。","بۇ ئالىم بىلىمگە تولۇپ تاشقان بولۇپ، قەدىمكى ئەدەبىيات تەتقىقاتىدا چوڭقۇر بىلىمگە ئىگە.","Bu alim bilimge tolup tashqan bolup, qedimki edebiyat tetqiqatida chongqur bilimge ige."]],"汉文帝":[["汉文帝是中国历史上著名的仁君。","خەنۋېندى جۇڭگو تارىخىدىكى مەشھۇر مېھرىبان پادىشاھتۇر.","Xenwëndi junggo tarixidiki meshhur mëhriban padishahtur."]],"汉滨":[["汉滨是安康市的主要城区。","خەنبىن ئەنكاڭ شەھىرىنىڭ ئاساسلىق شەھەر رايونىدۇر.","Xenbin enkang shehirining asasliq sheher rayonidur."]],"渐新统":[["渐新统属于第三纪的早期阶段。","ئولىگوسېن تۈزۈلمىسى ئۈچىنچى دەۋرنىڭ دەسلەپكى باسقۇچىغا تەۋە.","Oligosën tüzülmisi üchinchi dewrning deslepki basquchigha tewe."]],"潮热":[["潮热是更年期常见的症状。","ئىسسىق لەپلەپ چىقىش ئاياللارنىڭ ئۆسمۈرلۈك دەۋرىدىن ئۆتۈش مەزگىلىدە كۆپ ئۇچرايدىغان ئالامەت.","Issiq leplep chiqish ayallarning ösmürlük dewridin ötüsh mezgilide köp uchraydighan alamet."]],"澎湖群岛":[["澎湖群岛由众多小岛组成。","پېڭخۇ ئاراللىرى كۆپلىگەن كىچىك ئاراللاردىن تەركىب تاپقان.","Pëngxu aralliri köpligen kichik arallardin terkib tapqan."]],"潜进":[["士兵潜进敌方阵地执行任务。","ئەسكەرلەر يوشۇرۇن دۈشمەن ئورنىغا كىرىپ ۋەزىپە ئىجرا قىلدى.","Eskerler yoshurun düshmen ornigha kirip wezipe ijra qildi."]],"潼南区":[["潼南区是重庆市下辖的一个行政区。","تۇڭنەن رايونى چۇڭچىڭ شەھىرىگە قاراشلىق بىر مەمۇرىي رايون.","Tungnen rayoni chungching shehirige qarashliq bir memuriy rayon."]],"滴石":[["滴石是钟表中重要的计时部件。","تامچە تاش سائەتتە ۋاقىت ئۆلچەيدىغان مۇھىم زاپچاس ھېسابلىنىدۇ.","Tamche tash sa'ette waqit ölcheydighan muhim zapchas hësablinidu."]],"满口之乎者也":[["他满口之乎者也，像个读书人。","ئۇنىڭ ئاغزى پۈتۈنلەي قەدىمىي كىتاب تىلىغا تولغان، خۇددى بىر ئوقۇمۇشلۇق ئادەمگە ئوخشايدۇ.","Uning aghzi pütünley qedimiy kitab tiligha tolghan, xuddi bir oqumushluq ademge oxshaydu."]],"湿答答":[["地板湿答答的，走路要小心。","پول نەم بولۇپ، مېڭىشتا ئېھتىيات قىلىش كېرەك.","Pol nem bolup, mëngishta ëhtiyat qilish kërek."]],"泻肚":[["吃坏肚子后出现了泻肚症状。","ئاشقازاننى بۇزۇپ قويغاندىن كېيىن ئىچ سۈرۈش ئالامىتى كۆرۈلدى.","Ashqazanni buzup qoyghandin këyin ich sürüsh alamiti körüldi."]],"濠江":[["濠江是广东的一条重要河流。","خاۋجياڭ گۇاڭدۇڭنىڭ مۇھىم دەرياسى.","Xawjyang guangdungning muhim deryasi."]],"灌木丛":[["茂密的灌木丛为小动物提供了庇护。","قويۇق چاتقاللىق كىچىك ھايۋانلارغا پاناھلىق بېرىدۇ.","Qoyuq chatqalliq kichik haywanlargha panahliq bëridu."]],"灰头麦鸡":[["灰头麦鸡在田野里活动频繁。","كۈلرەڭ باشلىق چۆل تاتارى قۇش ئېتىزلىقلاردا كۆپ ھەرىكەتلىنىدۇ.","Külreng bashliq chöl tatari qush ëtizliqlarda köp heriketlinidu."]],"乌孜别克族":[["乌孜别克族主要居住在中亚地区。","ئۆزبېك مىللىتى ئاساسلىقى ئوتتۇرا ئاسىيا رايونىدا ياشايدۇ.","Özbëk milliti asasliqi ottura asiya rayonida yashaydu."]],"烃化作用":[["烃化作用可使分子结构变得更加复杂。","ئالكانلاشتۇرۇش ئارقىلىق مولېكۇلا قۇرۇلمىسى تېخىمۇ مۇرەككەپ بولىدۇ.","Alkanlashturush arqiliq molëkula qurulmisi tëximu murekkep bolidu."]],"烤布蕾":[["烤布蕾是一道经典的甜点。","كرېم برۇلېيە كلاسسىك تاتلىق تائام.","Krëm brulëye klassik tatliq ta'am."]],"无损":[["这次合作无损双方利益，皆大欢喜。","بۇ ھەمكارلىق ئىككى تەرەپنىڭ مەنپەئەتىگە زىيان يەتكۈزمەيدۇ، ھەممە خۇشال.","Bu hemkarliq ikki terepning menpe'etige ziyan yetküzmeydu, hemme xushal."]],"无期":[["他因犯罪被判无期徒刑。","ئۇ جىنايەت سادىر قىلغانلىقى ئۈچۈن ئۆمۈر بويى قاماق جازاسىغا ھۆكۈم قىلىندى.","U jinayet sadir qilghanliqi üchün ömür boyi qamaq jazasigha höküm qilindi."]],"煮饭":[["煮饭需要半小时。","گۈرۈچ پىشۇرۇشقا يېرىم سائەت كېتىدۇ.","Gürüch pishurushqa yërim sa'et këtidu."]],"烟瘾":[["烟瘾犯了，他忍不住又抽了一支烟。","تاماكا خۇمارى قوزغىلىپ، ئۇ ئۆزىنى تۇتۇپ قالالماي يەنە بىر تال تاماكا چەكتى.","Tamaka xumari qozghilip, u özini tutup qalalmay yene bir tal tamaka chekti."]],"焚香":[["寺庙里常常有人焚香祈福。","ئىبادەتخانىلاردا دائىم كىشىلەر خۇشپۇراق ئوت يېقىپ دۇئا قىلىدۇ.","Ibadetxanilarda da'im kishiler xushpuraq ot yëqip du'a qilidu."]],"牌型":[["这张牌型很稀有。","بۇ كارتىنىڭ تۈرى ناھايىتى ئاز ئۇچرايدۇ.","Bu kartining türi nahayiti az uchraydu."]],"墙纸":[["他给房间换了新墙纸。","ئۇ ئۆيگە يېڭى تام قەغىزى ئالماشتۇردى.","U öyge yëngi tam qeghizi almashturdi."]],"争取时效":[["我们必须争取时效，完成任务。","بىز چوقۇم ۋاقىتنى تالىشىپ، ۋەزىپىنى ئورۇندىشىمىز كېرەك.","Biz choqum waqitni taliship, wezipini orundishimiz kërek."]],"狄更斯":[["狄更斯是英国文学的巨匠。","دىككېنس ئەنگلىيە ئەدەبىياتىنىڭ ئۇلۇغ ئۇستىسى.","Dikkëns en'gliye edebiyatining ulugh ustisi."]],"狐狸座":[["狐狸座是星座之一。","تۈلكە يۇلتۇز ئورنى يۇلتۇز تۈركۈملىرىنىڭ بىرى.","Tülke yultuz orni yultuz türkümlirining biri."]],"猴拳":[["他练习的猴拳动作生动有趣。","ئۇ مەشىق قىلغان مايمۇن مۇشتى ھەرىكەتلىرى جانلىق ۋە قىزىقارلىق.","U meshiq qilghan maymun mushti heriketliri janliq we qiziqarliq."]],"玉门":[["玉门是古代的重要关隘。","يۈمەن قەدىمكى زاماندىكى مۇھىم ئۆتكەل.","Yümen qedimki zamandiki muhim ötkel."]],"玉米粉":[["玉米粉可以用来制作各种面食。","مەككەجۆۋەرى ئۇنى ھەر خىل ئۇن تائاملىرىنى تەييارلاشقا ئىشلىتىشكە بولىدۇ.","Mekkejöweri uni her xil un ta'amlirini teyyarlashqa ishlitishke bolidu."]],"现在分词":[["动词的现在分词形式表示主动。","پېئىلنىڭ ھازىرقى زامان سۈپەت دەرىجىسى ئاكتىپلىقنى بىلدۈرىدۇ.","Pë'ilning hazirqi zaman süpet derijisi aktipliqni bildüridu."]],"玻意耳":[["玻意耳定律是气体定律之一。","بويل قانۇنى گاز قانۇنلىرىنىڭ بىرىدۇر.","Boyl qanuni gaz qanunlirining biridur."]],"献祭":[["他们举行仪式献祭。","ئۇلار مۇراسىم ئۆتكۈزۈپ قۇربانلىق تەقدىم قىلدى.","Ular murasim ötküzüp qurbanliq teqdim qildi."]],"瓷砖":[["瓷砖铺满整个墙面。","فارفور كاھىش پۈتۈن تام يۈزىگە يېيىلغان.","Farfor kahish pütün tam yüzige yëyilghan."]],"现世报":[["他做了坏事，现世报很快就来了。","ئۇ يامانلىق قىلدى، دۇنيالىق جازاسى دەرھال كەلدى.","U yamanliq qildi, dunyaliq jazasi derhal keldi."]],"产婆":[["产婆帮助产妇顺利生产。","كۆندۈرگۈچى ئانا تۇغقۇچىغا تۇغۇتنى ئوڭۇشلۇق ئېلىپ بېرىشقا ياردەم قىلدى.","Köndürgüchi ana tughquchigha tughutni ongushluq ëlip bërishqa yardem qildi."]],"畜力":[["依靠畜力耕作田地。","ھايۋان كۈچىگە تايىنىپ ئېتىز-ئېرىقنى ئىشلەڭ.","Haywan küchige tayinip ëtiz-ëriqni ishleng."]],"疲弱":[["身体疲弱的人需要多休息。","بەدەن زەئىپلەشكەن كىشىلەر كۆپرەك ئارام ئېلىشى كېرەك.","Beden ze'ipleshken kishiler köprek aram ëlishi kërek."]],"痘苗":[["接种痘苗可以预防疾病。","چېچەك ۋاكسىنىسى ئەملەش ئارقىلىق كېسەللىكنىڭ ئالدىنى ئېلىشقا بولىدۇ.","Chëchek waksinisi emlesh arqiliq kësellikning aldini ëlishqa bolidu."]],"痛不欲生":[["他痛不欲生。","ئۇ ئازاب-ئوقۇبەتتە چىدىيالمىدى.","U azab-oqubette chidiyalmidi."]],"发行红利股":[["公司发行红利股。","شىركەت پايدا ئەسھىمىنى تارقاتتى.","Shirket payda es'himini tarqatti."]],"异见":[["他的异见引发争议。","ئۇنىڭ ئوخشىمىغان پىكرى تالاش-تارتىش پەيدا قىلدى.","Uning oxshimighan pikri talash-tartish peyda qildi."]],"白颈长尾雉":[["白颈长尾雉的尾巴特别长。","ئاق بوينىلىق ئۇزۇن قۇيرۇق قىرغاۋۇلنىڭ قۇيرۇقى ئالاھىدە ئۇزۇن.","Aq boyniliq uzun quyruq qirghawulning quyruqi alahide uzun."]],"白发人送黑发人":[["白发人送黑发人，令人悲痛。","ئاق ساچلىق كىشى قارا ساچلىق كىشىنى يوقلىسا، كىشىنى قايغۇغا سالىدۇ.","Aq sachliq kishi qara sachliq kishini yoqlisa, kishini qayghugha salidu."]],"白相人":[["这个白相人说话很圆滑。","بۇ ئاقچى ئادەم سۆزلىگەندە بەك ماھىر.","Bu aqchi adem sözligende bek mahir."]],"百兽":[["百兽在森林中自由自在地奔跑。","يۈز خىل ھايۋان ئورماندا ئەركىن يۈگۈرىدۇ.","Yüz xil haywan ormanda erkin yügüridu."]],"突击检查":[["领导突然进行突击检查。","رەھبەر تۇيۇقسىز تەكشۈرۈش ئېلىپ باردى.","Rehber tuyuqsiz tekshürüsh ëlip bardi."]],"突击步枪":[["士兵使用突击步枪射击。","ئەسكەرلەر تۇيۇقسىز ئېتىلىدىغان مىلتىق بىلەن ئاتتى.","Eskerler tuyuqsiz ëtilidighan miltiq bilen atti."]],"突然间":[["突然间下起了大雨。","تۇيۇقسىز ھالدا قاتتىق يامغۇر ياغدى.","Tuyuqsiz halda qattiq yamghur yaghdi."]],"纸上谈兵":[["纸上谈兵没有用。","قەغەز ئۈستىدە ئۇرۇش توغرىسىدا سۆزلەشنىڭ پايدىسى يوق.","Qeghez üstide urush toghrisida sözleshning paydisi yoq."]],"纸样":[["纸样是服装设计的参考模板。","قەغەز ئۈلگە كىيىم لايىھەلەشنىڭ پايدىلىنىش قېلىپىدۇر.","Qeghez ülge kiyim layiheleshning paydilinish qëlipidur."]],"结亲":[["两家商议后决定结亲联姻。","ئىككى ئائىلە مەسلىھەتلىشىپ ئاندىن قۇدا بولۇشقا قارار قىلدى.","Ikki a'ile meslihetliship andin quda bolushqa qarar qildi."]]};